window.ITEMS=[{"id":"wed-marriage-gift-deduction","stage":"wedding","kind":"tax","who":"부부","title":"혼인·출산 증여재산공제","summary":"직계존속(부모·조부모)에게 혼인일 전후 2년 안에 증여받으면 기존 증여재산공제와 별도로 1억원까지 공제돼요. 출산 때 받는 공제와 합쳐서 1억원이 한도예요.","loses":"혼인일 전후 2년을 벗어나 증여받으면 이 1억원 공제를 쓸 수 없어 그만큼 증여세 과세표준이 늘어요.","steps":["혼인신고일을 기준으로 전후 2년 안에 증여 시점을 잡아요","홈택스에서 증여세 신고를 하며 혼인출산공제를 적용해요","파혼하면 사유 발생 달의 말일부터 3개월 안에 반환하면 증여가 없던 것으로 봐요"],"where":"홈택스 hometax.go.kr, 국세상담센터 126","amount":"최대 1억원(직계존속 전체 합산, 혼인·출산 공제 합산)","eligibility":"거주자인 자녀가 직계존속에게 증여받는 경우, 증여일 2024.1.1. 이후","timing":{"anchor":"report","from_days":-730,"to_days":730,"label":"혼인일 전후 2년 이내 증여분"},"region":"전국","sources":[{"org":"국세청 국세상담센터","title":"혼인·출산 증여재산공제 자주묻는 Q&A","url":"https://call.nts.go.kr/call/qna/selectQnaInfo.do?mi=2787&ctgId=CTG12222","checked":"2026-09-13"}],"verified":true,"note":"원문 Q&A 예시는 혼인신고일을 기준으로 계산해요. 증여세 신고 기한은 이번에 연 원문에 없어 적지 않았어요. 부부가 각자 자기 부모에게 받을 때 1인당 따로 적용되는지는 원문에 명시돼 있지 않아요."},{"id":"wed-seoul-deposit-interest","stage":"wedding","kind":"housing","who":"부부","title":"서울시 신혼부부 임차보증금 이자지원","summary":"서울시가 추천한 신혼부부가 협약은행에서 전월세보증금 대출을 받으면 시가 이자 일부를 대신 내줘요. 부부 합쳐 생애 1회만 받을 수 있어요.","loses":"입주일과 전입일 중 빠른 날부터 3개월이 지나면 신규 신청이 안 돼서 최대 연 4.5%의 이자지원을 놓쳐요.","steps":["국민·하나·신한은행 지점에서 대출한도와 소득요건을 먼저 상담해요","임대차계약(보증금 7억원 이하, 월세는 환산보증금 기준)을 맺어요","대출추천서는 잔금일 2개월 전부터 서울주거포털에서 신청해요","추천서를 받아 은행에 대출을 신청해요(하나은행은 모바일 앱 신청 가능)"],"where":"서울주거포털 housing.seoul.go.kr, 국민·하나·신한은행. 문의는 서울시 전월세종합지원센터 02-2133-1200~8","amount":"대출 최대 3억원(보증금의 90% 이내), 이자지원 최대 연 4.5%(소득별 1.0~3.0% + 추가 최대 1.5%)","eligibility":"서울시민이거나 대출 후 1개월 안에 서울로 전입할 예정이어야 해요. 대출신청일 기준 혼인신고 7년 이내이거나 6개월 이내 예식 예정이어야 해요. 부부합산 연소득 1억 3천만원 이하이고 부부 모두 무주택이어야 해요. 대출명의자는 세대주여야 해요","timing":{"anchor":"report","from_days":-180,"to_days":2557,"label":"혼인신고일부터 7년 이내(예식 6개월 전부터), 입주일·전입일 중 빠른 날부터 3개월 이내 신청"},"region":"서울","sources":[{"org":"서울특별시","title":"신혼부부 임차보증금 이자지원사업 변경계획 공고(서울특별시공고 제2025-3067호, 2025.10.31.)","url":"https://housing.seoul.go.kr/site/main/file/download/uu/dd2ac64daadb47af88d851d41105b2b1","checked":"2026-09-13"},{"org":"서울주거포털","title":"신혼부부 임차보증금 사업개요","url":"https://housing.seoul.go.kr/site/main/content/sh01_0400800","checked":"2026-09-13"}],"verified":true,"note":"2025.11.20. 이후 신규·연장 신청분부터 출산·입양 시 자녀 1명당 4년 연장(최장 12년), 환산 임차보증금 기준이 적용돼요. 기본 지원은 2년+2년이에요. 예비신혼부부는 대출 후 6개월 안에 혼인관계증명서를 내지 않으면 이자지원이 끊기고 즉시 상환해야 해요. 예산에 따라 일일 신청 건수가 제한될 수 있어요. 본인 부담금리 최저는 연 1.0%예요."},{"id":"wed-venue-cancellation-penalty","stage":"wedding","kind":"contract","who":"부부","title":"예식장 계약해제 위약금 기준(소비자분쟁해결기준)","summary":"소비자 사정으로 예식장 계약을 해제할 때 예식일까지 남은 기간에 따라 위약금이 정해져 있어요. 계약 후 15일 안에 청약을 철회하면 위약금 없이 계약금을 모두 돌려받아요.","loses":"해제 날짜가 하루 늦어 구간이 바뀌면 물어야 하는 위약금이 총비용의 10%p 넘게 늘어나요.","steps":["예식 150일 전까지 해제하면 계약금을 돌려받아요. 계약 15일 뒤 해제면 서면으로 알리고 동의받은 계약추진비는 뺄 수 있어요","예식 60일 전까지: 계약금과 총비용의 10%예요","예식 30일 전까지: 계약금과 총비용의 20%예요","예식 29~10일 전: 계약금과 총비용의 40%예요","예식 9~1일 전: 계약금과 총비용의 50%예요","예식 당일: 계약금과 총비용의 70%예요"],"where":"소비자상담센터 1372, 한국소비자원 kca.go.kr","amount":null,"eligibility":"예식장 이용 계약을 맺은 소비자예요. 사업자 사정으로 해제하면 29일 전 이후에는 계약금을 돌려받고 총비용의 70%를 배상받아요","timing":{"anchor":"wedding","from_days":null,"to_days":-150,"label":"예식 150일 전까지 해제하면 계약금 환급"},"region":"전국","sources":[{"org":"공정거래위원회","title":"소비자분쟁해결기준 개정안 시행(보도참고자료 2025.12.18.)","url":"https://www.ftc.go.kr/www/downloadBbsFile.do?atchmnflNo=52377","checked":"2026-09-13"},{"org":"법제처 찾기쉬운 생활법령정보","title":"결혼준비자 > 예식장 이용 계약","url":"https://www.easylaw.go.kr/CSP/CnpClsMain.laf?csmSeq=1894&ccfNo=2&cciNo=3&cnpClsNo=2","checked":"2026-09-13"}],"verified":true,"note":"2025년 12월 개정 전에는 29일 전부터 당일까지 일률 35%였어요. 개정으로 소비자 사정 해제는 40%·50%·70%로 나뉘었어요. 150일 전 무상 해제라도 계약 15일 이후에는 계약추진비를 뺄 수 있게 됐어요. 계약 후 제공된 재화·서비스에 한해, 미리 서면으로 알리고 동의받은 비용만 해당해요. 소비자분쟁해결기준은 따로 약정이 없을 때 적용되는 합의 권고 기준이에요. 표준약관상 계약금은 예식비용의 10% 이하예요.","bands":[{"until_days":-150,"band":"150일 전까지","rule":"계약금 환급"},{"until_days":-60,"band":"60일 전까지","rule":"계약금 + 총비용 10%"},{"until_days":-30,"band":"30일 전까지","rule":"계약금 + 총비용 20%"},{"until_days":-10,"band":"29~10일 전","rule":"계약금 + 총비용 40%"},{"until_days":-1,"band":"9~1일 전","rule":"계약금 + 총비용 50%"},{"until_days":0,"band":"예식 당일","rule":"계약금 + 총비용 70%"}]},{"id":"wed-didimdol-newlywed","stage":"wedding","kind":"housing","who":"부부","title":"신혼부부전용 구입자금(디딤돌)","summary":"혼인 7년 이내이거나 3개월 안에 결혼할 무주택 생애최초 주택구입 부부에게 주택도시기금이 낮은 금리로 주택구입자금을 빌려줘요.","loses":"소유권이전등기 접수일부터 3개월이 지나거나 혼인신고일부터 7년이 지나면 신청할 수 없어 시중 주택담보대출 금리를 써야 해요.","steps":["기금포털에서 자산·소득 자가진단을 해요","매매계약 후 기금e든든 비대면 신청이나 수탁은행 방문 신청을 해요","소유권이전등기 전(등기했다면 접수일부터 3개월 이내)에 대출을 신청해요","결혼예정자로 받았다면 대출 후 3개월 안에 배우자가 올라간 주민등록등본을 내요"],"where":"주택도시기금 nhuf.molit.go.kr(기금e든든), 기금 수탁은행. 문의는 주택도시보증공사 콜센터 1566-9009","amount":"최대 3.2억원(LTV 80%, 수도권·규제지역 70%, DTI 60%), 연 2.55~3.85%","eligibility":"부부합산 연소득 8.5천만원 이하, 순자산 5.11억원 이하예요(2026년 기준). 세대원 전원이 무주택이고 생애최초 구입이어야 해요. 혼인 7년 이내이거나 3개월 이내 결혼예정이어야 해요. 주택은 평가액 6억원 이하·전용 85㎡ 이하예요","timing":{"anchor":"report","from_days":-90,"to_days":2557,"label":"혼인신고일부터 7년 이내(결혼 3개월 전부터 가능), 등기 후 3개월 이내 신청"},"region":"전국","sources":[{"org":"국토교통부 주택도시기금","title":"신혼부부전용 구입자금","url":"https://nhuf.molit.go.kr/FP/FP05/FP0503/FP05030601.jsp","checked":"2026-09-13"}],"verified":true,"note":"2025.6.27. 이전 계약분은 한도 4억원이었어요. 금리는 국토교통부 고시로 바뀌어요. 자녀 우대금리는 1자녀 연 0.3%p·2자녀 0.5%p·다자녀 0.7%p이고, 2025.3.24. 신규접수분부터 자녀 1명당 5년(최대 15년) 적용해요. 2024.8.12.~2026.12.31. 중도상환분은 중도상환수수료가 면제돼요. 출산 후에는 신생아 특례 디딤돌대출도 있는데, 대출접수일 기준 2년 내 출산(2023.1.1. 이후 출생아) 가구가 대상이에요."},{"id":"wed-beotimmok-newlywed","stage":"wedding","kind":"housing","who":"부부","title":"신혼부부전용 전세자금(버팀목)","summary":"혼인 7년 이내이거나 3개월 안에 결혼할 무주택 세대주에게 주택도시기금이 전세자금을 낮은 금리로 빌려줘요.","loses":"잔금지급일과 전입일 중 빠른 날부터 3개월이 지나면 신청할 수 없어 은행 전세대출 금리를 써야 해요.","steps":["기금포털에서 소득·자산 요건을 먼저 확인해요","임대차계약을 맺고 보증금의 5% 이상을 내요","잔금일과 전입일 중 빠른 날부터 3개월 안에 기금e든든이나 수탁은행에서 대출과 보증(HUG·HF)을 함께 신청해요"],"where":"주택도시기금 nhuf.molit.go.kr(기금e든든), 기금 수탁은행. 문의는 주택도시보증공사 1566-9009, 한국주택금융공사 1688-8114","amount":"수도권 최대 2.5억원, 수도권 외 1.6억원(보증금의 80% 이내), 연 1.9~3.3%","eligibility":"부부합산 연소득 7.5천만원 이하, 순자산 3.45억원 이하예요(2026년 기준). 세대원 전원이 무주택이어야 해요. 혼인 7년 이내이거나 3개월 이내 결혼예정이어야 해요. 임차 주택은 전용 85㎡ 이하, 보증금 수도권 4억원 이하예요","timing":{"anchor":"report","from_days":-90,"to_days":2557,"label":"혼인신고일부터 7년 이내, 잔금일·전입일 중 빠른 날부터 3개월 이내 신청"},"region":"전국","sources":[{"org":"국토교통부 주택도시기금","title":"신혼부부전용 전세자금","url":"https://nhuf.molit.go.kr/FP/FP05/FP0502/FP05020401.jsp","checked":"2026-09-13"}],"verified":true,"note":"2025.6.27. 이전 계약분은 수도권 3억원·수도권 외 2억원 한도였어요. 기본 2년, 최장 10년 이용 가능하고 미성년 1자녀당 2년 추가(최장 20년)돼요. 자녀 우대금리는 2025.3.24. 신규접수분부터 자녀 1명당 4년(최대 12년) 적용해요. 금리는 국토교통부 고시로 바뀌어요. 출산 후 신생아 특례 버팀목대출은 대출접수일 기준 2년 내 출산(2023.1.1. 이후 출생아) 가구가 대상이에요."},{"id":"wed-marriage-tax-credit","stage":"wedding","kind":"tax","who":"부부","title":"결혼세액공제","summary":"2024년 1월 1일부터 2026년 12월 31일 사이에 혼인신고한 사람은 혼인신고한 해의 연말정산에서 산출세액 50만원까지 공제받아요. 부부가 각자 받을 수 있어 최대 100만원이에요.","loses":"2026년 12월 31일을 넘겨 혼인신고하면 이 공제가 없고, 신고한 해에 반영하지 않으면 다음 해로 넘겨 받을 수 없어요(이월공제 불가).","steps":["혼인신고를 2026년 12월 31일까지 마쳐요","혼인신고한 해의 연말정산(다음 해 1~2월)에서 부부 각자 결혼세액공제를 적용해요","연말정산에서 빠뜨렸다면 5월 종합소득세 신고나 경정청구로 정정해요"],"where":"회사 연말정산, 홈택스 hometax.go.kr, 국세상담센터 126","amount":"1인당 50만원(부부 합계 최대 100만원)","eligibility":"2024.1.1.~2026.12.31. 혼인신고(혼인신고서를 지자체에 접수한 날 기준), 생애 1회","timing":{"anchor":"report","from_days":0,"to_days":null,"label":"혼인신고를 2026년 12월 31일까지 하고, 신고한 해 귀속 연말정산에서 공제"},"region":"전국","sources":[{"org":"국세청","title":"꿀 같은 신혼, 최대 100만원의 결혼세액공제도 잊지 마세요(보도참고자료 2025.1.19.)","url":"https://www.nts.go.kr/comm/nttFileDownload.do?fileKey=01fd8ca0832de9fe899b64a19df4edd1","checked":"2026-09-13"},{"org":"국세청","title":"연말정산 때 놓친 공제? 5월에 한 번 더 살펴보세요(보도참고자료 2024.5.7.)","url":"https://www.nts.go.kr/comm/nttFileDownload.do?fileKey=290d07b87dca652598392b94dddcb73b","checked":"2026-09-13"}],"verified":true,"note":"한시 제도로 2024~2026년 혼인신고분만 적용돼요. 2027년 이후 연장 여부는 법령 원문(조세특례제한법)을 열지 못해 확인하지 못했어요. 국세청 자료는 '결혼한 근로자' 기준으로 안내해요. 경정청구 기한 숫자는 원문에서 추출하지 못해 적지 않았어요."},{"id":"wed-yearend-spouse-split","stage":"wedding","kind":"tax","who":"부부","title":"맞벌이 부부 연말정산 공제 명의 나누기","summary":"신용카드 등 소득공제는 총급여의 25%를 넘게 쓴 금액부터 적용되고, 의료비는 총급여의 3%를 넘어야 공제돼요. 그래서 누구 명의로 쓰고 누가 공제받는지에 따라 환급액이 달라져요.","loses":"결혼 준비로 지출이 큰 해에 명의를 따지지 않으면 공제 한도나 문턱 때문에 부부 합산 환급액이 줄 수 있어요.","steps":["홈택스 > 장려금·연말정산 > 편리한 연말정산 > 맞벌이 부부 절세안내에서 조합을 비교해요","배우자가 간소화자료 제공에 동의하면 배우자의 의료비 등을 조회할 수 있어요","소득이 없는 배우자는 연 소득 100만원(근로소득만 있으면 총급여 500만원) 이하일 때 기본공제 대상으로 올려요"],"where":"홈택스 hometax.go.kr, 국세상담센터 126","amount":null,"eligibility":"신용카드 등 소득공제는 근로소득자 본인 명의 카드로 쓴 금액에만 적용돼요","timing":{"anchor":"report","from_days":0,"to_days":null,"label":"혼인신고한 해의 지출부터, 다음 해 1~2월 연말정산"},"region":"전국","sources":[{"org":"국세청","title":"꿀 같은 신혼, 최대 100만원의 결혼세액공제도 잊지 마세요(보도참고자료 2025.1.19.)","url":"https://www.nts.go.kr/comm/nttFileDownload.do?fileKey=01fd8ca0832de9fe899b64a19df4edd1","checked":"2026-09-13"}],"verified":true,"note":"국세청 자료 사례에서 총급여 7천만원 초과자의 신용카드 소득공제 한도는 200만원, 이하자는 300만원으로 안내돼 있어요(2024년 귀속 기준). 한도는 세법 개정으로 바뀔 수 있어 해마다 확인이 필요해요."},{"id":"wed-one-household-rent-credit","stage":"wedding","kind":"tax","who":"부부","title":"혼인신고 후 한 세대 판정(월세·청약저축 공제)","summary":"혼인신고한 부부는 함께 살지 않아도 같은 1세대로 봐요. 12월 31일 기준으로 세대에 주택이 있으면 세대원 모두 월세액 세액공제, 주택청약저축 소득공제, 주택임차차입금 원리금 상환액 공제를 받지 못해요.","loses":"배우자가 주택을 가진 상태에서 혼인신고한 해에 월세 공제를 그대로 넣으면 공제가 부인돼 추가 납부가 생길 수 있어요.","steps":["혼인신고한 해 12월 31일 기준으로 부부 중 주택 보유자가 있는지 확인해요","주택이 있으면 월세·청약저축·전세대출 원리금 공제를 연말정산에서 빼요","주택담보대출 이자 공제는 주택 명의자와 대출 명의자가 같은지 확인해요"],"where":"회사 연말정산, 홈택스 hometax.go.kr, 국세상담센터 126","amount":null,"eligibility":null,"timing":{"anchor":"report","from_days":0,"to_days":null,"label":"혼인신고한 해 12월 31일 기준으로 판정"},"region":"전국","sources":[{"org":"국세청","title":"꿀 같은 신혼, 최대 100만원의 결혼세액공제도 잊지 마세요(보도참고자료 2025.1.19.)","url":"https://www.nts.go.kr/comm/nttFileDownload.do?fileKey=01fd8ca0832de9fe899b64a19df4edd1","checked":"2026-09-13"}],"verified":true,"note":null},{"id":"wed-marriage-merge-two-houses","stage":"wedding","kind":"tax","who":"부부","title":"혼인합가 1세대 2주택 비과세 특례","summary":"각자 1주택을 가진 두 사람이 혼인해 1세대 2주택이 되면, 혼인한 날부터 10년 안에 파는 주택은 1세대 1주택으로 보고 양도세 비과세 여부를 판단해요.","loses":"혼인신고일부터 10년이 지나 팔면 이 특례를 쓸 수 없어 양도소득세가 과세될 수 있어요.","steps":["혼인신고일과 부부 각자 주택 취득일을 정리해요","혼인신고일부터 10년 안에 먼저 팔 주택을 정해요","양도 전 국세상담센터나 세무서에 비과세 요건을 확인해요"],"where":"국세상담센터 126, 관할 세무서, 홈택스","amount":null,"eligibility":"혼인 당시 두 사람이 각각 1주택을 가진 경우예요. 1주택과 분양권 조합이면 이 특례 대신 일시적 2주택 규정을 적용해요","timing":{"anchor":"report","from_days":0,"to_days":3652,"label":"혼인신고일부터 10년 이내 양도"},"region":"전국","sources":[{"org":"국세청 국세상담센터","title":"2주택 보유자 등에 대한 비과세 특례 자주묻는 Q&A(혼인에 따른 2주택 특례)","url":"https://call.nts.go.kr/call/qna/selectQnaInfo.do?mi=2013&ctgId=CTG11745","checked":"2026-09-13"}],"verified":true,"note":"2024년 11월 12일 이후 양도분부터 5년에서 10년으로 늘었어요. '혼인한 날'은 혼인신고한 날이에요."},{"id":"wed-newlywed-special-supply","stage":"wedding","kind":"housing","who":"부부","title":"신혼부부 특별공급(아파트 청약)","summary":"국민주택과 전용 85㎡ 이하 민영주택의 일부를 혼인 7년 이내 무주택 신혼부부에게 따로 공급해요. 한 세대당 한 번만 당첨될 수 있어요.","loses":"입주자 모집공고일에 혼인신고일부터 7년이 지났으면 신혼부부 특별공급에 넣을 수 없어 일반공급 경쟁만 남아요.","steps":["청약홈에서 모집공고의 소득·자산 기준표를 확인해요","부부와 세대원 모두 무주택인지 주민등록등본으로 확인해요","청약홈에서 특별공급 신청일에 신혼부부 유형으로 청약해요"],"where":"한국부동산원 청약홈 applyhome.co.kr","amount":null,"eligibility":"모집공고일 현재 혼인기간 7년 이내여야 해요(혼인관계증명서의 신고일 기준). 무주택세대구성원이어야 해요. 월평균소득은 전년도 도시근로자 가구당 월평균소득의 140%(배우자 소득이 있으면 160%) 이하여야 해요. 이 기준을 넘어도 부동산가액 기준을 충족하면 돼요","timing":{"anchor":"report","from_days":0,"to_days":2557,"label":"모집공고일 기준 혼인신고일부터 7년 이내"},"region":"전국","sources":[{"org":"법제처 찾기쉬운 생활법령정보","title":"아파트 분양받기 > 특별공급 > 신혼부부","url":"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&csmSeq=1773&ccfNo=2&cciNo=1&cnpClsNo=1","checked":"2026-09-13"}],"verified":true,"note":"혼인기간 중 자녀를 출산(임신·입양 포함)했으면 1순위예요. 공공분양 신혼부부 특별공급은 소득 130%(맞벌이 200%) 이하, 예비신혼부부·6세 이하 자녀를 둔 가구도 신청할 수 있어요. 청약홈 원문은 직접 열지 않고 법제처 생활법령(주택공급에 관한 규칙 제41조 인용)으로 확인했어요."},{"id":"wed-seoul-public-wedding-hall","stage":"wedding","kind":"benefit","who":"부부","title":"서울시 더 아름다운 결혼식(공공예식장)","summary":"서울시 공공예식장을 대관료 없이 쓰고, 조건을 맞추면 의자·테이블 같은 비품비를 최대 100만원 지원받는 사업이에요.","loses":"신청일부터 예식 당일까지 부부 중 한 사람이라도 서울 주소를 유지하지 않거나 예식 후 만족도 조사·후기에 참여하지 않으면 비품비 최대 100만원을 못 받아요.","steps":["상담전화 1899-2154나 상담채팅으로 사전상담을 해요","누리집 상단 '상담신청'으로 원하는 예식장을 신청하면 지정업체가 연락해요","결혼식 신청서·동의서와 주민등록초본(생활권자는 재직·재학증명서)을 내요","예식 후 문자로 오는 만족도 조사와 후기를 작성해요"],"where":"서울시 더 아름다운 결혼식 wedding.seoulwomen.or.kr, 상담 1899-2154","amount":"대관료 무료(일부 예식장 별도 대관료), 비품비 최대 100만원","eligibility":"서울시 거주자·생활권자는 신청할 수 있어요. 예비부부의 부모가 서울에 살아도 신청할 수 있어요. 생활권자는 서울 소재 직장인·대학생·자영업자예요. 비품비는 부부 중 한 명이 신청일부터 예식 당일까지 서울 거주를 유지해야 받아요","timing":{"anchor":"wedding","from_days":null,"to_days":0,"label":"2027년 예식은 2026년 3월 3일 10시부터 상시 신청, 예식 당일까지 서울 주소 유지"},"region":"서울","sources":[{"org":"서울특별시 더 아름다운 결혼식","title":"사업안내","url":"https://wedding.seoulwomen.or.kr/intro","checked":"2026-09-13"},{"org":"서울특별시 더 아름다운 결혼식","title":"서울시 예식장 지원 혜택 공지","url":"https://wedding.seoulwomen.or.kr/notice/1560","checked":"2026-09-13"}],"verified":true,"note":"혜택 공지는 비품비 100만원을 '2025년 기준, 2026년도는 변동 가능'으로 적고 있어요. 사업안내 페이지는 현재도 최대 100만원으로 안내해요. 예산이 소진되면 조기 마감될 수 있어요. 예식일은 바꿀 수 없어 취소 후 다시 예약해야 해요. 예약확정 후 3번 취소하면 1년간 예약할 수 없어요. 공공예식장을 중복 계약하면 모두 취소될 수 있어요."},{"id":"wed-nhis-spouse-dependent","stage":"wedding","kind":"benefit","who":"부부","title":"건강보험 배우자 피부양자 등록","summary":"소득·재산 요건을 맞춘 배우자는 직장가입자의 피부양자로 등록해 따로 지역보험료를 내지 않을 수 있어요. 등록은 직장가입자가 신고해야 해요.","loses":"신고가 늦으면 피부양자 취득일이 신고서 제출일로 밀려 그 사이 배우자에게 지역보험료가 부과될 수 있어요.","steps":["건강보험공단 누리집 모의계산에서 배우자가 피부양자 요건에 맞는지 확인해요","직장가입자가 피부양자 자격(취득·상실) 신고서와 혼인관계증명서(등본으로 확인되면 생략)를 준비해요","공단 누리집·지사나 회사를 통해 신고해요"],"where":"국민건강보험공단 nhis.or.kr(민원 > 피부양자 자격취득 및 상실 신고), 가까운 공단 지사","amount":null,"eligibility":"소득 합계가 연 2천만원 이하여야 해요. 사업소득이 없어야 해요(사업자등록이 없으면 연 500만원 이하까지 인정). 재산과표는 5.4억원 이하이거나, 5.4억원 초과 9억원 이하이면서 연 소득 1천만원 이하여야 해요","timing":{"anchor":"report","from_days":0,"to_days":null,"label":"자격변동일부터 90일 이내 신고하면 그날로 소급 인정"},"region":"전국","sources":[{"org":"국민건강보험공단","title":"피부양자 자격의 인정기준 중 소득 및 재산요건","url":"https://www.nhis.or.kr/nhis/policy/wbhada07400m01.do","checked":"2026-09-13"},{"org":"국민건강보험공단","title":"피부양자 취득안내","url":"https://www.nhis.or.kr/nhis/policy/wbhada07300m01.do","checked":"2026-09-13"},{"org":"국민건강보험공단","title":"피부양자 자격취득 및 상실 신고","url":"https://www.nhis.or.kr/nhis/minwon/minwonServiceBoard.do?mode=view&articleNo=10945798","checked":"2026-09-13"}],"verified":true,"note":"공단 원문은 '직장가입자의 자격취득일 또는 가입자의 자격변동일부터 90일 이내' 소급으로 적고 있어요. 혼인신고가 이 기산일에 해당하는지는 원문에 나와 있지 않아 to_days를 비워 두었어요. 사실혼은 공증·판결상 성립일부터 90일이에요. 지역가입자에서 전환될 때 취득일이 1일이 아니면 신고일이 속한 달까지 지역보험료가 부과돼요. 피부양자가 기혼이면 부부 모두 소득요건을 충족해야 해요."},{"id":"wed-newlywed-hope-town","stage":"wedding","kind":"housing","who":"부부","title":"신혼희망타운","summary":"신혼부부, 예비신혼부부, 6세 이하 자녀를 둔 한부모가족만 신청할 수 있는 공공분양주택이에요.","loses":"모집공고일에 혼인 7년이 지났고 6세 이하 자녀(태아 포함)도 없으면 신청 자격이 없어져요.","steps":["마이홈포털에서 신혼희망타운 모집공고를 확인해요","소득·자산 기준을 공고문으로 확인해요","주택가격이 자산기준을 넘으면 입주 때까지 신혼희망타운 전용 주택담보장기대출에 가입해요"],"where":"마이홈포털 myhome.go.kr, 청약홈·LH 청약플러스","amount":null,"eligibility":"모집공고일 현재 혼인 7년 이내이거나, 6세 이하 자녀(태아 포함)가 있거나, 예비신혼부부여야 해요. 무주택세대구성원이어야 해요. 월평균소득은 130%(부부 모두 소득이 있으면 200%) 이하예요","timing":{"anchor":"report","from_days":null,"to_days":2557,"label":"모집공고일 기준 혼인 7년 이내(예비신혼부부도 가능)"},"region":"전국","sources":[{"org":"법제처 찾기쉬운 생활법령정보","title":"아파트 분양받기 > 특별공급 > 신혼부부(신혼희망타운주택)","url":"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&csmSeq=1773&ccfNo=2&cciNo=1&cnpClsNo=1","checked":"2026-09-13"}],"verified":true,"note":"자산기준 금액과 전용 대출 조건은 공고마다 달라 적지 않았어요."},{"id":"wed-marriage-report","stage":"wedding","kind":"deadline","who":"부부","title":"혼인신고","summary":"혼인은 신고한 때부터 법적 효력이 생겨요. 신고 기간은 따로 없고, 등록기준지·주소지·현재지 중 어느 시(구)·읍·면 사무소에서도 할 수 있어요.","loses":"결혼세액공제 대상 기간, 혼인합가 주택 비과세 기간, 신혼부부 대출·청약의 혼인기간은 모두 혼인신고일을 기준으로 계산해요. 그래서 신고 시점에 따라 받을 수 있는 공제와 자격이 달라져요.","steps":["혼인신고서에 부부 인적사항과 성년 증인 2명의 서명을 받아요","부부 신분증을 챙겨 가까운 구청·읍·면 사무소에 내요. 한 사람만 가면 다른 사람 신분증이나 인감증명서를 함께 내요","수리 후 혼인관계증명서를 발급해 대출·청약·연말정산 서류로 보관해요"],"where":"시(구)·읍·면 사무소(신고 장소 제한 없음), 대법원 전자가족관계등록시스템 efamily.scourt.go.kr. 문의는 사용자지원센터 1899-2732","amount":null,"eligibility":"혼인하려는 당사자 두 사람과 성년 증인 2명의 서명이 필요해요","timing":{"anchor":"report","from_days":null,"to_days":null,"label":"신고 기간 없음. 신고서를 낸 날이 혼인일로 계산돼요"},"region":"전국","sources":[{"org":"법제처 찾기쉬운 생활법령정보","title":"결혼준비자 > 혼인신고하기 > 혼인신고","url":"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&csmSeq=1894&ccfNo=3&cciNo=2&cnpClsNo=1","checked":"2026-09-13"},{"org":"법제처 찾기쉬운 생활법령정보","title":"가족관계 등록 > 혼인신고방법","url":"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&csmSeq=707&ccfNo=4&cciNo=1&cnpClsNo=1","checked":"2026-09-13"}],"verified":true,"note":"전자가족관계등록시스템에서 혼인신고를 온라인으로 낼 수 있는지와 조건은 원문 본문이 스크립트로만 열려 확인하지 못했어요. 수리된 혼인신고는 취소할 수 없어요."},{"id":"wed-seoul-mirinae-purchase-rental","stage":"wedding","kind":"housing","who":"부부","title":"서울시 일반주택형 미리내집(신혼·신생아 매입임대주택Ⅱ)","summary":"SH가 사들인 오피스텔·도시형생활주택 등을 신혼부부, 예비 신혼부부, 신생아 가구에 시세 60~70% 임대료로 빌려줘요. 거주 중 출산하면 10년 거주 후 장기전세주택으로 우선 이주를 신청할 수 있어요.","loses":"청약 접수 기간이 3일 정도로 짧아 공고를 놓치면 다음 차수 모집까지 기다려야 해요.","steps":["SH 누리집과 서울시 공지에서 차수별 모집공고를 확인해요","소득·자산 기준을 공고문으로 확인해요","접수 기간에 SH 인터넷 청약으로 신청해요"],"where":"서울주택도시개발공사(SH) 인터넷 청약, 서울시","amount":"임대료 시세 60%(수급자·소득 80% 이하) 또는 70%(소득 130% 이하, 맞벌이 200% 이하)","eligibility":"공고일 기준 무주택 세대구성원이어야 해요. 소득은 도시근로자 가구원수별 월평균소득 130% 이하(맞벌이 200% 이하)예요. 총자산은 3억 6,200만원 이하예요(2026년 1차)","timing":{"anchor":"report","from_days":null,"to_days":null,"label":"차수별 모집공고 기간(2026년 1차는 8월 31일~9월 2일 접수)"},"region":"서울","sources":[{"org":"서울특별시","title":"서울시, '일반주택형 미리내집' 128세대 공급(2026-08-28)","url":"https://scpm.seoul.go.kr/seoul-policy/evt0303","checked":"2026-09-13"}],"verified":true,"note":"2026년 1차 접수는 이미 끝났어요. 기본 최장 10년, 자녀가 있으면 최장 14년 거주할 수 있어요. 혼인기간 요건은 이번 원문에 없어 적지 않았어요. 차수마다 기준이 바뀔 수 있어요."},{"id":"wed-planner-cancellation-penalty","stage":"wedding","kind":"contract","who":"부부","title":"결혼준비대행(스드메) 계약해제·청약철회 기준","summary":"스튜디오·드레스·메이크업을 묶은 결혼준비대행 계약은 서비스 개시 전 소비자 사정으로 해지하면 총 대행요금의 10%를 빼고 돌려주는 것이 분쟁해결기준이에요. 박람회장이나 온라인에서 맺은 계약은 법정 청약철회 기간이 있어요.","loses":"업체 사업장 밖 박람회장에서 맺은 계약은 계약서를 받은 날부터 14일, 온라인 계약은 7일이 지나면 위약금 없이 철회할 수 있는 기회가 사라져요.","steps":["박람회장이 업체 자체 사업장인지 확인해요. 업체 사업장에서 연 박람회는 방문판매법 청약철회 대상이 아니에요","계약서를 받은 날을 적어두고 14일(박람회장)·7일(온라인) 안에 철회 여부를 정해요","철회나 해지는 내용증명 등 서면으로 보내요","현금보다 신용카드로 결제하면 부당한 해지 거절 때 카드사에 결제 거부를 요청할 수 있어요"],"where":"소비자상담센터 1372, 한국소비자원 kca.go.kr","amount":null,"eligibility":"결혼준비대행업체와 계약한 소비자예요. 서비스 개시 이후 해지하면 이미 발생한 비용과 남은 금액의 10%를 빼고 돌려받아요","timing":{"anchor":"wedding","from_days":null,"to_days":null,"label":"계약서를 받은 날부터 14일(박람회장) 또는 7일(온라인) 안에 청약철회"},"region":"전국","sources":[{"org":"법제처 찾기쉬운 생활법령정보","title":"결혼준비자 > 결혼준비대행서비스 계약","url":"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&csmSeq=1894&ccfNo=2&cciNo=3&cnpClsNo=1","checked":"2026-09-13"}],"verified":true,"note":"원문은 2026년 8월 15일 기준으로 작성됐다고 표시돼요. 업체가 합리적 이유 없이 담당 웨딩플래너를 바꿔 해제하면 계약금 전액 환급이 가능하다는 한국소비자원 분쟁조정 사례도 같은 원문에 있어요."},{"id":"wed-wedding-price-disclosure","stage":"wedding","kind":"contract","who":"부부","title":"결혼서비스 가격 표시 의무(중요정보고시)","summary":"2025년 11월 12일부터 예식장업과 결혼준비대행업 사업자는 기본서비스·선택품목의 항목별 요금과 위약금·환급기준을 표시해야 해요. 표시는 누리집 또는 한국소비자원 참가격 중 한 곳과 계약서 표지에 해요.","loses":"계약 전에 공개된 항목별 요금과 환급기준을 확인하지 않으면 계약 후 선택품목 추가 비용이나 불리한 환급기준을 비교할 기회를 놓쳐요.","steps":["참가격 price.go.kr > 서비스가격정보 > 결혼서비스 > 중요정보 공개에서 업체를 찾아요","참가격에 없으면 업체 누리집의 가격표를 확인해요","결혼준비대행업체는 제휴 스튜디오·드레스·메이크업 업체별 요금과 환급기준이 따로 적혀 있는지 봐요","계약서 표지에 같은 내용이 있는지 확인해요"],"where":"한국소비자원 참가격 price.go.kr, 업체 누리집. 문의는 소비자상담센터 1372","amount":null,"eligibility":"예식장업(결혼식 장소 대여업)과 결혼준비대행업(사진촬영·드레스 대여·메이크업 등 결혼 준비 대행업)이 대상이에요","timing":{"anchor":"wedding","from_days":null,"to_days":null,"label":"업체 계약 전"},"region":"전국","sources":[{"org":"공정거래위원회","title":"「중요한 표시·광고사항 고시」 개정·시행(보도자료 2025.11.12. 조간, 고시 제2025-9호)","url":"https://www.korea.kr/briefing/pressReleaseView.do?newsId=156727458","checked":"2026-09-13"}],"verified":true,"note":"시행 후 6개월 계도기간이 있었어요. 계도기간 종료 후 점검과 과태료 상한은 뉴스 보도로만 확인해 숫자를 적지 않았어요. 사업자가 필요 이상의 개인정보나 회원가입을 요구해 접근을 막으면 표시의무 위반이 될 수 있다고 공정위가 안내했어요."},{"id":"wed-move-in-report","stage":"wedding","kind":"deadline","who":"부부","title":"신혼집 전입신고·확정일자","summary":"이사한 날부터 14일 안에 새 주소지 주민센터나 정부24에서 전입신고를 해야 해요. 전세·월세면 전입신고와 함께 임대차계약서에 확정일자를 받아야 보증금 우선변제권이 생겨요.","loses":"14일을 넘기면 5만원 이하 과태료가 부과될 수 있어요. 전입이 늦으면 대항력(전입 다음 날 0시부터 발생)과 우선변제권이 늦게 생겨 보증금 보호 순위가 밀릴 수 있어요.","steps":["이사 당일 정부24나 주민센터에서 전입신고를 해요","같은 날 임대차계약서에 확정일자를 받아요","세대주와 전 세대주가 다르면 세대 합가·편입 방식에 맞춰 신고해요"],"where":"새 주소지 읍·면사무소·동 주민센터, 정부24 gov.kr","amount":null,"eligibility":"세대주 또는 세대주의 위임을 받은 배우자·직계혈족 등이 신고해요","timing":{"anchor":"wedding","from_days":null,"to_days":null,"label":"이사한 날부터 14일 이내(보증금 보호는 이사 당일 신고가 유리)"},"region":"전국","sources":[{"org":"법제처 찾기쉬운 생활법령정보","title":"이사 > 전입신고하기","url":"https://www.easylaw.go.kr/CSP/CnpClsMain.laf?csmSeq=666&ccfNo=4&cciNo=1&cnpClsNo=1","checked":"2026-09-13"}],"verified":true,"note":"기한 기준이 이사일이라 anchor는 예식일로 두고 일수는 비웠어요. 신혼부부 전세대출·서울시 이자지원의 신청 기한(잔금일·전입일 중 빠른 날부터 3개월)도 전입일과 연결돼요."},{"id":"wed-marriage-leave","stage":"wedding","kind":"work-right","who":"부부","title":"결혼 경조사휴가","summary":"근로기준법에는 경조사휴가 규정이 없어요. 회사 취업규칙이나 단체협약에 정해 두었다면 그 내용에 따라요.","loses":"회사 규정의 결혼휴가 일수·사용 기한·유급 여부를 확인하지 않으면 규정상 쓸 수 있는 휴가를 쓰지 못하고 지나갈 수 있어요.","steps":["회사 취업규칙이나 단체협약에서 결혼 경조사휴가 일수와 사용 기한을 확인해요","유급인지 무급인지, 휴일이 포함되는지 확인해요","예식일과 신혼여행 일정에 맞춰 신청해요"],"where":"회사 인사팀(취업규칙·단체협약), 고용노동부 누리집 moel.go.kr 빠른인터넷상담","amount":null,"eligibility":null,"timing":{"anchor":"wedding","from_days":null,"to_days":null,"label":"회사 취업규칙에 따름"},"region":"전국","sources":[{"org":"고용노동부","title":"빠른인터넷상담: 경조휴가 유급 여부 답변","url":"https://www.moel.go.kr/minwon/fastcounsel/fastcounselView.do?inetDcssMngId=202402071356515911000","checked":"2026-09-13"},{"org":"법제처 국가법령정보센터","title":"국가공무원 복무규정 [별표 2] 경조사별 휴가 일수표(개정 2023.7.18.)","url":"https://www.law.go.kr/flDownload.do?flSeq=135030859","checked":"2026-09-13"}],"verified":true,"note":"국가공무원은 복무규정 별표 2에 따라 본인 결혼 5일이에요. 지방공무원·교원 등은 각 규정을 따로 확인해야 해요. 공무원 결혼휴가의 사용 기한은 이번에 연 원문에 없어 적지 않았어요."},{"id":"pre-live-vaccine-pregnancy-interval","stage":"pre","kind":"vaccine","who":"엄마","title":"풍진 등 생백신 접종과 임신 간격(공적 기관 안내)","summary":"공적 기관 안내: 질병관리청 국가건강정보포털은 풍진 같은 약독화 생백신은 임신 중에 사용하지 말아야 한다고 적고 있어요. 같은 글은 임신하기 최소한 한 달 전에 접종하는 것이 바람직하다고 적어요. 예방접종도우미도 임신을 생백신 접종의 금기사항으로 들어요. 개인 일정은 의료기관과 상의해요.","loses":"임신 시도 직전에야 이 안내를 알게 되면 공적 기관 안내의 한 달 간격 때문에 시도 일정을 다시 잡아야 할 수 있어요.","steps":["국가건강정보포털 '정상임신관리(임신 전 관리)' 안내를 확인해요","예방접종도우미 누리집에서 본인 예방접종 기록(증명서)을 확인해요","접종 여부와 시기는 진료 의사와 상의해요"],"where":"질병관리청 예방접종도우미(nip.kdca.go.kr), 국가건강정보포털(health.kdca.go.kr), 의료기관·보건소","amount":null,"eligibility":null,"timing":{"anchor":"start","from_days":null,"to_days":-30,"label":"질병관리청 안내 문구: 임신하기 최소한 한달 전에 접종"},"region":"전국","sources":[{"org":"질병관리청 국가건강정보포털","title":"정상임신관리(임신 전 관리)","url":"https://health.kdca.go.kr/healthinfo/biz/health/gnrlzHealthInfo/gnrlzHealthInfo/gnrlzHealthInfoView.do?cntnts_sn=6388","checked":"2026-09-13"},{"org":"질병관리청 예방접종도우미","title":"예방접종 주의사항 및 금기사항","url":"https://nip.kdca.go.kr/irhp/infm/goVcntInfo.do?menuLv=1&menuCd=114","checked":"2026-09-13"},{"org":"질병관리청 예방접종도우미","title":"풍진","url":"https://nip.kdca.go.kr/irhp/infm/goVcntInfo.do?menuLv=1&menuCd=1122","checked":"2026-09-13"}],"verified":true,"note":"국가건강정보포털 해당 글은 2026-08-10 수정본이에요. 수두 백신의 임신 간격 문구와 성인 풍진 항체검사·접종 비용 지원은 이번에 연 질병관리청 원문에서 찾지 못해 넣지 않았어요. 일부 비공식 자료는 MMR 접종 후 4주로 적어요."},{"id":"pre-fertility-checkup-support","stage":"pre","kind":"benefit","who":"부부","title":"임신 사전건강관리 지원(필수 가임력 검사비)","summary":"여성은 난소기능검사(AMH)와 부인과 초음파 비용을 지원해요. 남성은 정액검사(정자정밀형태검사) 비용을 지원해요. 보건소에 먼저 신청해 검사의뢰서를 받은 뒤 검사하는 순서예요.","loses":"신청과 검사의뢰서 없이 검사부터 받거나 검사일로부터 1개월 안에 청구하지 않으면 여성 최대 13만원, 남성 최대 5만원 지원을 놓칠 수 있어요.","steps":["e보건소 온라인이나 주소지 관할 보건소 방문으로 검사비 지원을 신청해요","검사의뢰서를 받아요(5일 이내 발급)","신청일로부터 3개월 이내에 검사의뢰서를 가지고 검사해요","검사일로부터 1개월 이내에 검사비를 청구해요","검사비를 받아요"],"where":"e보건소 공공보건포털(e-health.go.kr) 또는 주소지 관할 보건소","amount":"여성 최대 13만원, 남성 최대 5만원","eligibility":"검사를 원하는 20~49세 남녀가 대상이에요. 결혼·자녀 여부는 따지지 않아요. 15~19세 부부(예비부부·사실혼 포함)와 내국인 배우자가 있는 외국인도 대상이에요. 29세 이하(제1주기)·30~34세(제2주기)·35~49세(제3주기) 주기별 1회, 최대 3회예요.","timing":{"anchor":"start","from_days":null,"to_days":0,"label":"임신 시도 전, 연령 주기마다 1회. 검사는 신청일로부터 3개월 이내, 청구는 검사일로부터 1개월 이내"},"region":"전국","sources":[{"org":"보건복지부 e보건소","title":"임신 사전건강관리 지원사업","url":"https://www.e-health.go.kr/gh/caSrvcGud/selectMdclSupGudInfo.do?heBiz=PG00003&menuId=200097","checked":"2026-09-13"},{"org":"서울시 임신·출산 정보센터","title":"임신 사전건강관리 지원","url":"https://seoul-agi.seoul.go.kr/pragnant-previous-support","checked":"2026-09-13"},{"org":"보건복지부","title":"2025년부터 미혼 남녀도 가임력 검사 받으세요(보도자료)","url":"https://www.mohw.go.kr/board.es?mid=a10503010100&bid=0027&list_no=1484145&act=view","checked":"2026-09-13"}],"verified":true,"note":"2025년 1월 1일부터 미혼 포함 20~49세로 대상이 넓어졌어요. 생애 1회에서 주기별 최대 3회로도 늘었어요. 2026년에는 지원 인원이 20만 1천명에서 35만 9천명으로 늘어난다고 정책브리핑(2025.12.17)에 나와요. 검사의뢰서 없이 받은 검사를 지원하지 않는지는 원문에 없어요. 원문에는 검사의뢰서가 있어야 한다고만 적혀 있어요."},{"id":"pre-infertility-treatment-support","stage":"pre","kind":"benefit","who":"부부","title":"난임부부 시술비 지원","summary":"체외수정·인공수정 시술비 중 일부와 전액본인부담금, 비급여 일부를 지원해요. 출산당 25회까지 받을 수 있어요. 시술마다 보건소에서 지원결정통지서를 먼저 받아야 해요.","loses":"지원결정통지서가 나오기 전에 생긴 시술비는 지원되지 않아요. 통지서 없이 시술을 시작하면 회당 최대 110만원(신선배아)까지의 지원을 못 받아요.","steps":["난임 진단을 받고 의사의 난임진단서를 준비해요","주소지 관할 보건소를 방문하거나 e보건소·정부24에서 온라인으로 신청해요. 사실혼 부부의 첫 신청은 보건소를 방문해서 해요","보건소가 자격을 확인한 뒤 지원결정통지서를 발급해요","통지서 유효기간 안에 시술 기관에 통지서를 내고 시술을 시작해요","다음 회차마다 다시 신청해요"],"where":"주소지 관할 보건소, e보건소(e-health.go.kr), 정부24(gov.kr)","amount":"1회당 체외수정 신선배아 최대 110만원, 동결배아 최대 50만원, 인공수정(자궁내 정자주입) 최대 30만원. 비급여 배아동결비 최대 30만원, 유산방지제·착상보조제 각 최대 20만원","eligibility":"법적 혼인 또는 사실혼 부부가 대상이에요. 부부 중 1명 이상이 주민등록된 대한민국 국적이어야 해요. 부부 모두 건강보험에 가입돼 있어야 하고, 의사의 난임진단서를 내야 해요. 출산당 25회(체외수정 최대 20회, 인공수정 최대 5회)까지예요.","timing":{"anchor":"start","from_days":null,"to_days":null,"label":"시술마다 시술 시작 전에 신청해 지원결정통지서를 받아요"},"region":"전국","sources":[{"org":"정부24","title":"난임부부 시술비 지원","url":"https://www.gov.kr/portal/service/serviceInfo/SME000000100","checked":"2026-09-13"},{"org":"보건복지부 e보건소","title":"난임부부 시술비 지원","url":"https://www.e-health.go.kr/gh/caSrvcGud/selectMdclSupGudInfo.do?heBiz=PG00001&menuId=200009","checked":"2026-09-13"},{"org":"서울시 임신·출산 정보센터","title":"서울시 난임부부 시술비 지원사업","url":"https://seoul-agi.seoul.go.kr/ifc-csp","checked":"2026-09-13"},{"org":"대한민국 정책브리핑(보건복지부)","title":"2026년 보건·복지 정책 이렇게 달라집니다","url":"https://www.korea.kr/multi/visualNewsView.do?newsId=148956615","checked":"2026-09-13"}],"verified":true,"note":"지원결정통지서 유효기간이 원문끼리 달라요. 정부24(최종수정 2026.06.15)는 발급일로부터 3개월로 적어요. 정책브리핑(2025.12.17)은 2026년부터 6개월로 늘어난다고 적어요. 발급받을 때 보건소에 확인해야 해요. 소득 기준 폐지 여부와 연령별 금액 차등은 이번에 연 원문에 없어서 넣지 않았어요."},{"id":"pre-seoul-ivf-stop-support","stage":"pre","kind":"benefit","who":"부부","title":"서울형 난임시술 중단 의료비 지원","summary":"서울시가 난임시술이 의학적 사유로 중단된 경우에도 본인부담금 등을 지원하는 사업이에요.","loses":"시술이 중단되면 지원이 끝난다고 여기고 넘어가면 본인부담금의 90%와 비급여 3종, 약제비, 냉동난자 해동비 지원을 못 받아요.","steps":["난임부부 시술비 지원결정통지서를 받고 시술을 진행해요","의학적 사유로 시술이 중단되면 주민등록 주소지 보건소에 지원 여부를 물어요"],"where":"주민등록 주소지 보건소, 서울시 임신·출산 정보센터(02-2133-9489)","amount":"중단 시 본인부담금의 90%, 비급여 3종, 약제비, 냉동난자 해동비","eligibility":"서울시에 사는 난임부부(사실혼 포함)가 대상이에요. 지원결정통지서를 2025.1.1. 이후에 발급받은 경우에 해당해요.","timing":{"anchor":"start","from_days":null,"to_days":null,"label":"시술이 의학적 사유로 중단됐을 때"},"region":"서울","sources":[{"org":"서울시 임신·출산 정보센터","title":"서울시 난임부부 시술비 지원사업","url":"https://seoul-agi.seoul.go.kr/ifc-csp","checked":"2026-09-13"}],"verified":true,"note":"원문에 중단 의료비의 신청 기한과 제출 서류는 나와 있지 않아요."},{"id":"pre-infertility-treatment-leave","stage":"pre","kind":"work-right","who":"부부","title":"난임치료휴가","summary":"인공수정·체외수정 등 난임치료를 받는 근로자가 청구하면 사업주는 연간 6일 이내 휴가를 줘야 해요. 처음 2일은 유급이에요. 남녀 근로자 모두 해당해요. 사업주는 청구 과정에서 알게 된 사실을 본인 뜻과 달리 남에게 알릴 수 없어요.","loses":"제도를 모르면 시술 날마다 연차를 쓰게 돼요. 연간 6일(유급 2일) 휴가를 그대로 날려요.","steps":["난임치료 일정을 확인해요","사업주에게 난임치료휴가를 청구해요. 사업 운영에 중대한 지장이 있으면 협의해서 시기를 바꿀 수 있어요","중소기업은 사업주가 유급 2일분 급여 지원을 고용센터에 신청해요"],"where":"재직 중인 사업장. 문의는 고용노동부 고용평등 상담(1551-9811)","amount":null,"eligibility":"인공수정 또는 체외수정 등 난임치료를 받는 근로자가 대상이에요.","timing":{"anchor":"start","from_days":null,"to_days":null,"label":"난임치료를 받는 해마다 연간 6일 이내"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"남녀고용평등과 일ㆍ가정 양립 지원에 관한 법률 제18조의3","url":"https://www.law.go.kr/법령/남녀고용평등과일ㆍ가정양립지원에관한법률/제18조의3","checked":"2026-09-13"},{"org":"대한민국 정책브리핑(고용노동부)","title":"2025년부터 달라지는 '난임치료휴가'","url":"https://www.korea.kr/multi/visualNewsView.do?newsId=148940189","checked":"2026-09-13"}],"verified":true,"note":"2025년 2월 23일부터 연간 3일(유급 1일)에서 6일(유급 2일)로 늘었어요. 중소기업 유급 2일분 정부 급여 지원의 금액 상한과 신청 기한, 시행령상 청구 절차는 이번에 원문으로 확인하지 못했어요."},{"id":"pre-seoul-vasectomy-tubal-reversal","stage":"pre","kind":"benefit","who":"부부","title":"정관·난관 복원 수술 지원(서울시)","summary":"영구피임시술을 받은 서울 시민이 임신·출산을 위해 정관·난관 복원 시술을 받으면 비용을 지원해요.","loses":"수술 받은 해가 지나 신청하면(12월 시술은 다음 해 1월 말 이후) 생애 1회 최대 100만원 지원을 못 받아요.","steps":["복원 시술 후 진료비 영수증, 세부내역서, 복원 시술 진단서, 통장사본을 준비해요","수술 받은 그 해 안에 자치구 보건소를 방문해 신청해요"],"where":"주소지 자치구 보건소","amount":"최대 100만원(생애 1회)","eligibility":"정관·난관 절제술이나 결찰술을 받은 뒤 임신·출산을 위해 복원 시술을 받은 서울 시민이 대상이에요. 남성은 만 55세 이하(2026년 기준 1970.1.1. 이후 출생)예요. 여성은 만 49세 이하(2026년 기준 1976.1.1. 이후 출생)예요.","timing":{"anchor":"start","from_days":null,"to_days":null,"label":"정·난관 복원 시술을 받은 해당연도 내 신청(12월 시술은 다음 해 1월 말까지)"},"region":"서울","sources":[{"org":"서울시 임신·출산 정보센터","title":"정관·난관 복원 수술 지원","url":"https://seoul-agi.seoul.go.kr/coffin-restore","checked":"2026-09-13"}],"verified":true,"note":null},{"id":"pre-seoul-korean-medicine-infertility","stage":"pre","kind":"benefit","who":"부부","title":"서울시 한의약 난임치료 지원사업","summary":"원인불명 난임 진단을 받고 자연임신을 바라는 서울 부부에게 한의약 첩약 비용을 지원해요. 3개월 집중치료 뒤 2개월 관찰기간이 이어져요.","loses":"모르고 한의원 난임치료를 받으면 첩약 비용의 대부분을 직접 내요.","steps":["원인불명 난임 진단을 확인해요","서울시 임신·출산 정보센터 누리집이나 주민등록지·직장소재지 보건소에서 신청해요","해당 연도 모집 기간과 참여 한의원을 확인해요"],"where":"서울시 임신·출산 정보센터(seoul-agi.seoul.go.kr), 주민등록지 또는 직장소재지 보건소","amount":"3개월 첩약 비용의 90%(상한 120만원), 수급자·차상위는 100%","eligibility":"신청일 기준 서울시에 주민등록된 부부가 대상이에요. 여성은 만 45세 이하여야 해요. 원인불명 난임 진단을 받은 경우만 신청할 수 있어요. 결혼한 부부와 사실혼 부부 모두 돼요.","timing":{"anchor":"start","from_days":null,"to_days":null,"label":"해당 연도 모집 기간 안에 신청"},"region":"서울","sources":[{"org":"서울시 임신·출산 정보센터","title":"서울시 한의약 난임치료 지원 사업이란?","url":"https://seoul-agi.seoul.go.kr/infertility-treatment-support","checked":"2026-09-13"}],"verified":true,"note":"서울시 임신·출산 정보센터 사업 안내 페이지에는 사업 연도와 모집 기간이 적혀 있지 않아요. 신청 전에 보건소에서 올해 모집 여부를 확인해요."},{"id":"conf-pregnancy-birth-medical-voucher","stage":"preg-confirm","kind":"benefit","who":"엄마","title":"건강보험 임신·출산 진료비 지원(국민행복카드)","summary":"임신·출산 진료비와 처방 약제·치료재료 구입비를 국민행복카드 이용권으로 지원해요. 2세 미만 영유아 진료비와 처방 약제·치료재료 본인부담금에도 쓸 수 있어요.","loses":"이용권 발급일 전에 낸 진료비에는 거슬러 적용되지 않아요. 신청이 늦으면 그 사이 산전 진료비를 바우처로 결제하지 못해요.","steps":["의료기관에서 임신 사실을 확인해요","국민건강보험공단 누리집·앱, 전화, 공단 지사·전담 금융기관, 정부24 맘편한 임신 중 한 곳에서 신청해요","국민행복카드를 발급받아 진료비·약제비 결제에 써요"],"where":"국민건강보험공단(누리집·앱·지사), 전담 금융기관, 정부24(gov.kr)","amount":"단태아 100만원, 다태아 기본 140만원(태아당 100만원이 되도록 추가 지급), 분만취약지 20만원 추가","eligibility":"임신·출산(유산·사산 포함)이 확인된 건강보험 가입자·피부양자예요. 의료급여 수급자 등은 빠져요.","timing":{"anchor":"due","from_days":-250,"to_days":730,"label":"임신 확인 후 바로 신청 가능. 신청과 사용은 분만예정일(출산·유산·사산일)로부터 2년까지, 발급 전 진료비는 소급 불가","to_anchor":"birth"},"region":"전국","sources":[{"org":"정부24","title":"건강보험 임신·출산 진료비 지원","url":"https://www.gov.kr/portal/service/serviceInfo/SD0000007672","checked":"2026-09-13"}],"verified":true,"note":null},{"id":"conf-health-center-folic-iron","stage":"preg-confirm","kind":"benefit","who":"엄마","title":"보건소 임산부 등록과 엽산제·철분제 지원","summary":"주소지 보건소에 임산부로 신고하면 엽산제와 철분제를 받을 수 있어요. 의약품은 보건소를 방문해야만 받을 수 있어요. 건강기능식품은 온라인으로 신청하고 택배로 받을 수 있어요.","loses":"임산부 신고를 안 하면 엽산제(최대 3개월분)와 철분제(최대 5개월분)를 받지 못하고 직접 사야 해요.","steps":["주소지 보건소에 임산부로 신고(등록)해요","의약품은 보건소를 방문해 신청해요. 건강기능식품은 e보건소·아이마중 앱·정부24 맘편한 임신 중 한 곳에서 온라인으로 신청해요. 중복 신청은 안 돼요","임신 16주 이상이 되면 철분제를 신청해요"],"where":"주소지 관할 보건소, e보건소(e-health.go.kr), 정부24 맘편한 임신","amount":"엽산제 1인 최대 3개월분, 철분제 1인 최대 5개월분","eligibility":"임산부 신고를 마친 임산부 본인이 대상이에요. 엽산제는 임신 전·후 3개월, 철분제는 임신 16주 이상이에요.","timing":{"anchor":"due","from_days":-250,"to_days":-168,"label":"임신 확인 직후 등록. 엽산제는 임신 전·후 3개월, 철분제는 임신 16주부터"},"region":"전국","sources":[{"org":"보건복지부 e보건소","title":"엽산제·철분제 지원 안내","url":"https://www.e-health.go.kr/gh/caSrvcGud/selectParSupGudInfo.do?appFlg=05&menuId=200005","checked":"2026-09-13"},{"org":"정부24","title":"임산부 엽산제, 철분제 지원","url":"https://www.gov.kr/portal/service/serviceInfo/SD0000016094","checked":"2026-09-13"}],"verified":true,"note":"지자체마다 추가 수량과 나눠 주는 방법이 다를 수 있다고 원문에 적혀 있어요. 원문상 신청 대상은 임산부 신고를 마친 임산부 본인이에요. 그래서 임신 전 준비 단계에서 받을 수 있는지는 확인하지 못했어요. 마포구 보건소의 산전검사 등 추가 지원은 구 단위라 조사 범위에서 뺐어요."},{"id":"conf-mom-onestop-application","stage":"preg-confirm","kind":"benefit","who":"엄마","title":"맘편한 임신 원스톱 서비스(임신 관련 서비스 통합처리 신청)","summary":"정부24에서 엽산제, 철분제, 표준모자보건수첩, 맘편한 KTX 특실 할인, 임신·출산 진료비 지원, SRT 임산부 할인 등을 한 번에 신청해요. 난임부부 시술비, 출산전후·유사산 휴가급여, 고위험 임산부 의료비는 통합 안내를 받은 뒤 따로 신청해요.","loses":"서비스를 하나씩 따로 찾다 보면 KTX 특실 할인이나 SRT 임산부 할인, 지자체 임산부 배지·주차증 같은 항목을 빠뜨려요.","steps":["정부24에 접속해 간편인증·공동인증서로 본인인증을 해요. 또는 신분증을 들고 주민등록주소지 읍면동 주민센터나 보건소를 방문해요","임신정보 제공에 동의하거나 건강보험 임신·출산 진료비 지급신청서를 내요","원하는 서비스를 골라 한꺼번에 신청해요"],"where":"정부24(gov.kr), 주민등록주소지 읍면동 주민센터 또는 보건소","amount":null,"eligibility":"신청일 기준 임산부(내국인)가 대상이에요. 에너지바우처·산모신생아 건강관리 등 일부는 소득 요건이 있어요.","timing":{"anchor":"due","from_days":-250,"to_days":0,"label":"임신확인 이후부터 분만 예정일까지(개별 서비스마다 상이)"},"region":"전국","sources":[{"org":"정부24","title":"임신 관련 서비스 통합처리 신청(맘편한임신)","url":"https://www.gov.kr/portal/service/serviceInfo/174100000015","checked":"2026-09-13"}],"verified":true,"note":"KTX·SRT 할인 폭은 이번에 원문으로 확인하지 않았어요."},{"id":"conf-pregnancy-work-hour-reduction","stage":"preg-confirm","kind":"work-right","who":"엄마","title":"임신기 근로시간 단축","summary":"임신 후 12주 이내 또는 32주 이후인 여성 근로자가 1일 2시간 근로시간 단축을 신청하면 사용자는 허용해야 해요. 이를 이유로 임금을 깎을 수 없어요. 유산·조산 등 위험이 있는 근로자(고용노동부령)는 임신 전 기간에 쓸 수 있어요.","loses":"모르면 임금이 깎이지 않고 하루 2시간 줄여 일할 수 있는 임신 12주 이내 기간을 그냥 지나보내요.","steps":["임신 사실을 적은 의사 진단서를 준비해요. 같은 임신으로 다시 신청할 때는 생략해요","임신기간, 단축 시작·종료 예정일, 근무 시작·종료 시각을 적은 문서를 써요","단축 시작 예정일 3일 전까지 사용자에게 내요"],"where":"재직 중인 사업장. 문의는 고용노동부 고용평등 상담(1551-9811)","amount":null,"eligibility":"임신 후 12주 이내 또는 32주 이후 여성 근로자가 대상이에요. 유산·조산 위험 등이 있으면 임신 전 기간이 대상이에요. 1일 근로시간이 8시간 미만이면 1일 6시간이 되도록 허용할 수 있어요.","timing":{"anchor":"due","from_days":-250,"to_days":-196,"label":"임신 후 12주 이내 또는 32주 이후. 근로시간 단축 개시 예정일의 3일 전까지 신청"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"근로기준법 제74조","url":"https://www.law.go.kr/법령/근로기준법/제74조","checked":"2026-09-13"},{"org":"국가법령정보센터","title":"근로기준법 시행령 제43조의2","url":"https://www.law.go.kr/법령/근로기준법시행령/제43조의2","checked":"2026-09-13"},{"org":"대한민국 정책브리핑","title":"임신기 근로시간 단축 확대 시행","url":"https://www.korea.kr/news/policyNewsView.do?newsId=148940076","checked":"2026-09-13"}],"verified":true,"note":"2025년 2월 23일부터 사용 가능 시기가 '12주 이내, 36주 이후'에서 '12주 이내, 32주 이후'로 넓어졌어요. timing 범위는 임신 초기 구간만 담았어요. 32주 이후 구간은 출산예정일 -56일부터예요."},{"id":"conf-pregnancy-work-time-change","stage":"preg-confirm","kind":"work-right","who":"엄마","title":"임신기간 업무 시작·종료 시각 변경","summary":"임신 중인 여성 근로자가 1일 소정근로시간은 그대로 두고 출퇴근 시각을 바꾸겠다고 신청하면 사용자는 허용해야 해요. 다만 정상적인 사업 운영에 중대한 지장이 있거나 안전·건강 관련 법령을 어기게 되는 경우는 예외예요.","loses":"모르면 임신 기간 내내 혼잡한 출퇴근 시간대를 그대로 견뎌요.","steps":["임신 사실을 증명하는 의사 진단서를 준비해요. 같은 임신으로 다시 신청할 때는 생략해요","임신기간, 변경 예정 기간, 업무 시작·종료 시각을 적은 문서를 써요","변경 예정일 3일 전까지 사용자에게 내요"],"where":"재직 중인 사업장","amount":null,"eligibility":"임신 중인 여성 근로자","timing":{"anchor":"due","from_days":-250,"to_days":0,"label":"임신 기간 중, 변경 예정일의 3일 전까지 신청"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"근로기준법 제74조","url":"https://www.law.go.kr/법령/근로기준법/제74조","checked":"2026-09-13"},{"org":"국가법령정보센터","title":"근로기준법 시행령 제43조의3","url":"https://www.law.go.kr/법령/근로기준법시행령/제43조의3","checked":"2026-09-13"}],"verified":true,"note":null},{"id":"conf-prenatal-checkup-time","stage":"preg-confirm","kind":"work-right","who":"엄마","title":"태아검진 시간의 허용","summary":"임신한 여성근로자가 모자보건법에 따른 임산부 정기건강진단에 필요한 시간을 청구하면 사용자는 허용해야 해요. 그 시간을 이유로 임금을 깎을 수 없어요.","loses":"모르면 정기 검진 때마다 연차를 쓰거나 결근 처리로 임금이 깎여요.","steps":["검진 일정을 확인해요","사용자에게 임산부 정기건강진단 시간을 청구해요"],"where":"재직 중인 사업장","amount":null,"eligibility":"임신한 여성근로자","timing":{"anchor":"due","from_days":-250,"to_days":0,"label":"임신 기간 중 정기건강진단 때마다"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"근로기준법 제74조의2","url":"https://www.law.go.kr/법령/근로기준법/제74조의2","checked":"2026-09-13"}],"verified":true,"note":null},{"id":"conf-pregnancy-no-overtime","stage":"preg-confirm","kind":"work-right","who":"엄마","title":"임신 중 시간외근로 금지와 쉬운 업무 전환","summary":"사용자는 임신 중인 여성 근로자에게 시간외근로를 시킬 수 없어요. 근로자가 요구하면 쉬운 종류의 근로로 바꿔 줘야 해요.","loses":"모르면 임신 중에도 야근 요청을 거절하지 못하고 업무 전환도 요구하지 못해요.","steps":["임신 사실을 사업장에 알려요","필요하면 사용자에게 쉬운 종류의 근로로 바꿔 달라고 요구해요"],"where":"재직 중인 사업장","amount":null,"eligibility":"임신 중인 여성 근로자","timing":{"anchor":"due","from_days":-250,"to_days":0,"label":"임신 기간 전체"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"근로기준법 제74조","url":"https://www.law.go.kr/법령/근로기준법/제74조","checked":"2026-09-13"}],"verified":true,"note":null},{"id":"conf-delivery-hospital-check","stage":"preg-confirm","kind":"tip","who":"부부","title":"다니는 산부인과가 분만을 하는지 확인","summary":"건강보험심사평가원 자료를 보면 병·의원급 산부인과 1,571개 기관 중 실제 분만을 하는 곳은 260개예요. 분만 가능 의료기관 정보는 보건의료빅데이터개방시스템에서 찾아볼 수 있어요.","loses":"다니던 산부인과가 분만을 하지 않는 곳이면 임신 후기에 분만 병원을 새로 찾아 옮겨야 해요.","steps":["다니는 산부인과에 분만 진료를 하는지 물어요","보건의료빅데이터개방시스템(opendata.hira.or.kr)에서 분만 가능 의료기관을 찾아요. 메뉴는 공공데이터 > 공공데이터목록 > 요양기관이에요"],"where":"건강보험심사평가원 보건의료빅데이터개방시스템(opendata.hira.or.kr)","amount":null,"eligibility":null,"timing":{"anchor":"due","from_days":-250,"to_days":null,"label":"임신 확인 뒤 다닐 산부인과를 고를 때"},"region":"전국","sources":[{"org":"건강보험심사평가원","title":"분만 가능 의료기관 정보, 이제 보건의료빅데이터개방시스템에서 한눈에 확인하세요(보도자료)","url":"https://www.hira.or.kr/bbsDummy.do?pgmid=HIRAA020041000100&brdScnBltNo=4&brdBltNo=11852&pageIndex=1","checked":"2026-09-13"}],"verified":true,"note":"보도자료(2026-07-13)는 앞으로의 계획도 적고 있어요. 2026년 하반기에 심평원 누리집 'HIRA 건강지도'에서 위치 기반 분만 가능 의료기관 정보를 볼 수 있게 할 예정이라고 해요. 실제로 열렸는지는 확인하지 않았어요."},{"id":"conf-seoul-pregnant-transport","stage":"preg-confirm","kind":"benefit","who":"엄마","title":"서울시 임산부 교통비 지원","summary":"서울에 사는 임산부에게 교통비 바우처를 줘요. 바우처는 협약카드사의 본인 명의 신용·체크카드로 들어와요. 대중교통, 택시, 유류비(서울 소재 가맹점), 철도에 쓸 수 있어요.","loses":"사용 기한이 분만예정일로부터 12개월 되는 달 말일까지라 늦게 신청할수록 쓸 기간이 줄어요. 출산 후 6개월이 지나면 70~100만원 바우처를 못 받아요.","steps":["탄생육아 몽땅정보통에 회원가입하고 온라인 교육을 들어요","협약카드사의 본인 명의 카드와 본인 명의 휴대폰을 준비해요","몽땅정보통에서 온라인으로 신청해요. 또는 신분증·임신확인서를 들고 관할 동주민센터를 방문해 신청해요","카드에 바우처가 들어오면 교통 가맹점에서 써요"],"where":"탄생육아 몽땅정보통(umppa.seoul.go.kr), 관할 동주민센터, 다산콜센터 120","amount":"첫째 70만원, 둘째 80만원, 셋째 이상 100만원","eligibility":"신청일 기준 서울시 3개월 이상 계속 거주 임산부예요. 다문화가족 외국인 임산부도 포함해요. 협약카드사(신한·삼성·KB국민·우리·하나·BC) 본인 명의 카드가 있어야 해요.","timing":{"anchor":"due","from_days":-250,"to_days":183,"label":"임신 확인 후 ~ 출산 후 6개월 이내 신청. 임신 중 신청하면 분만예정일로부터 12개월이 되는 달 말일까지 사용","to_anchor":"birth"},"region":"서울","sources":[{"org":"서울시 임신·출산 정보센터","title":"임산부 교통비 지원","url":"https://seoul-agi.seoul.go.kr/pregnant-transportation-support","checked":"2026-09-13"},{"org":"서울시 탄생육아 몽땅정보통","title":"서울시 임산부 교통비 지원","url":"https://umppa.seoul.go.kr/hmpg/sprt/bzin/bzmgComtDetail.do?biz_mng_no=34B5EA8BEB354E2DB26136CFE52AEFF2","checked":"2026-09-13"},{"org":"서울시 내 손안에 서울","title":"둘째부터 지원금 더 드려요! 산후조리경비·임산부교통비","url":"https://mediahub.seoul.go.kr/archives/2017499","checked":"2026-09-13"}],"verified":true,"note":"2026년 3월 30일 개정 조례가 시행되면서 자녀 순위별 차등(70·80·100만원)이 됐어요. 1.1~3.29 신청분은 차액이 소급 지급됐어요. 2026년 7월 1일 신청분부터 서울 3개월(90일) 이상 계속 거주 요건이 생겼어요. 원문끼리 어긋나요. 서울시 기사(2026.03.18)는 신청 시작을 '임신 3개월', 사용 기한을 '출산 후 1년'으로 적어요. 현재 정보센터·몽땅정보통 안내는 '임신 확인 후', '분만예정일(출생일)로부터 12개월'로 적어요. 여기서는 현재 안내를 따랐어요. 몽땅정보통 다른 페이지(bzmgPageDetail)에는 70만원 단일·출산 후 3개월이라는 옛 내용이 남아 있어요."},{"id":"conf-seoul-35plus-medical","stage":"preg-confirm","kind":"benefit","who":"엄마","title":"서울시 35세 이상 임산부 의료비 지원","summary":"서울에 사는 35세 이상 임산부의 산전 외래 진료비 본인부담금을 지원해요. 임신 확인일부터 출산 전까지의 진찰료·검사료·주사료·처치료가 대상이고, 진료과는 따지지 않아요. 입원비, 약국 영수증, 제증명료는 빠져요.","loses":"출산(유산) 후 6개월이 지나면 임신 1회당 최대 50만원을 못 받아요. 영수증과 세부 진료내역서를 모아 두지 않으면 청구가 어려워요.","steps":["임신확인서를 받아 둬요","외래 진료 때마다 진료비 영수증, 세부 진료내역서, 결제 증빙을 보관해요","탄생육아 몽땅정보통에서 온라인으로 신청하거나 거주지 관할 보건소를 방문해 신청해요"],"where":"탄생육아 몽땅정보통(umppa.seoul.go.kr), 거주지 관할 보건소","amount":"임신 1회당 최대 50만원","eligibility":"신청일 기준 서울시에 살아야 해요. 분만예정 연도 기준 35세 이상이 대상이에요. 2026년 출산 예정자는 1991년생부터, 2027년 출산 예정자는 1992년생부터예요. 부부가 모두 외국인이면 빠져요.","timing":{"anchor":"due","from_days":-250,"to_days":183,"label":"임신 확인일 이후부터 출산(유산) 후 6개월 이내 신청","to_anchor":"birth"},"region":"서울","sources":[{"org":"서울시 임신·출산 정보센터","title":"35세 이상 임산부 의료비 지원사업","url":"https://seoul-agi.seoul.go.kr/preg-med-support","checked":"2026-09-13"},{"org":"서울특별시","title":"전국 최초 시행한 '35세 이상 임산부 의료비 지원'… '26년 확대 강화","url":"https://www.seoul.go.kr/news/news_report.do?tr_code=short&nttNo=456262","checked":"2026-09-13"},{"org":"서울시 내 손안에 서울","title":"35세 이상 임산부 누구나, 최대 50만 원 의료비 신청하세요!","url":"https://mediahub.seoul.go.kr/archives/2017850","checked":"2026-09-13"}],"verified":true,"note":"2026년 예산이 143억원으로 2025년(75억 2천만원)의 약 2배로 늘었다고 서울시 발표(2026-04-15)에 나와요."},{"id":"preg-nipt","stage":"preg-1","kind":"checkup-info","who":"엄마","title":"태아 DNA 선별검사(NIPT)","summary":"임신부 혈액 속 태아 DNA를 분석해 다운증후군, 에드워드증후군 등의 위험도를 평가하는 비침습적 선별검사예요. 병원마다 다를 수 있어요.","steps":[],"where":"산부인과 의료기관","amount":"비급여(의료기관마다 가격이 달라요)","eligibility":"선별검사(확진 검사 아님)","timing":{"anchor":"due","from_days":-210,"to_days":null,"label":"통상 임신 10주부터"},"region":"전국","sources":[{"org":"질병관리청 국가건강정보포털","title":"태아 DNA 선별검사 (NIPT 검사)","url":"https://health.kdca.go.kr/healthinfo/biz/health/gnrlzHealthInfo/gnrlzHealthInfo/gnrlzHealthInfoView.do?cntnts_sn=5530","checked":"2026-09-13"},{"org":"국민건강보험공단 비급여 정보 포털","title":"비침습적 산전검사(NIPT/니프티)","url":"https://www.nhis.or.kr/nbinfo/wbhfaa06200m28.do?mode=view&articleNo=11000202","checked":"2026-09-13"}],"verified":true,"note":"비급여 여부는 국민건강보험공단 비급여 정보 포털의 항목별 가격 정보에 올라 있는 것을 근거로 했어요. 해당 게시물 본문은 열리지 않아 가격은 넣지 않았어요."},{"id":"preg-nuchal-translucency","stage":"preg-1","kind":"checkup-info","who":"엄마","title":"태아 목덜미 투명대 측정","summary":"초음파로 태아 목덜미 부위의 피부 밑 두께를 재어 염색체 이상과 심장 기형의 위험도를 평가하는 선별검사예요. 병원마다 다를 수 있어요.","steps":[],"where":"산부인과 의료기관","amount":null,"eligibility":"선별검사(확진 검사 아님)","timing":{"anchor":"due","from_days":-203,"to_days":-182,"label":"통상 임신 11~14주"},"region":"전국","sources":[{"org":"질병관리청 국가건강정보포털","title":"초음파 태아 목덜미 투명대 측정","url":"https://health.kdca.go.kr/healthinfo/biz/health/gnrlzHealthInfo/gnrlzHealthInfo/gnrlzHealthInfoView.do?cntnts_sn=5516","checked":"2026-09-13"},{"org":"건강보험심사평가원","title":"초음파 검사의 급여기준(고시 제2023-105호)","url":"https://www.hira.or.kr/rc/insu/insuadtcrtr/InsuAdtCrtrPopup.do?mtgHmeDd=20230701&sno=1&mtgMtrRegSno=0001","checked":"2026-09-13"}],"verified":true,"note":"급여기준에는 임신 11~13주 정밀 초음파 1회 급여가 있어요. 목덜미 투명대 측정이 그 1회에 해당하는지는 원문에서 확인하지 못했어요. 함께 하는 혈액검사의 급여 여부도 확인하지 못해 금액을 비워 뒀어요."},{"id":"preg-ultrasound-coverage-first-trimester","stage":"preg-1","kind":"checkup-info","who":"엄마","title":"임신 초기 초음파 건강보험 급여 횟수","summary":"임신 13주 이하에는 일반 초음파 2회, 임신 11~13주에는 정밀 초음파 1회가 건강보험 급여로 인정돼요. 병원마다 다를 수 있어요.","loses":"주수 구간마다 인정되는 횟수를 넘긴 초음파는 원칙적으로 급여로 계산되지 않아요. 그만큼 비용이 늘 수 있어요.","steps":[],"where":"산부인과 의료기관","amount":"건강보험 급여(13주 이하 일반 2회, 11~13주 정밀 1회)","eligibility":"단태아 기준이에요. 다태아는 제2태아부터 소정점수의 50%를 산정해요. 태아 이상이 의심되는 등 급여기준에 적힌 사유가 있으면 횟수를 넘겨도 급여가 인정돼요.","timing":{"anchor":"due","from_days":null,"to_days":-189,"label":"통상 임신 13주 이하"},"region":"전국","sources":[{"org":"건강보험심사평가원","title":"초음파 검사의 급여기준(고시 제2023-105호, 2023.7.1. 시행)","url":"https://www.hira.or.kr/rc/insu/insuadtcrtr/InsuAdtCrtrPopup.do?mtgHmeDd=20230701&sno=1&mtgMtrRegSno=0001","checked":"2026-09-13"},{"org":"건강보험심사평가원","title":"임산부 초음파 주수별 급여 인정 횟수","url":"https://www.hira.or.kr/bbsDummy.do?pgmid=HIRAA010006011000&brdScnBltNo=4&brdBltNo=47499&pageIndex=1&pageIndex2=1","checked":"2026-09-13"}],"verified":true,"note":"고시 시행일은 2023.7.1.이에요. 2026년 이후 개정 고시가 있는지는 따로 확인하지 못했어요."},{"id":"preg-maternity-leave-split-before-birth","stage":"preg-1","kind":"work-right","who":"엄마","title":"출산전후휴가 출산 전 분할 사용","summary":"유산·사산 경험이 있거나, 휴가 청구 당시 만 40세 이상이거나, 유산·사산 위험 진단서를 낸 경우 출산 전 어느 때라도 출산전후휴가를 나누어 쓸 수 있어요. 출산 후 휴가는 연속 45일(다태아 60일) 이상이어야 해요.","loses":"해당 사유가 있어도 모르고 청구하지 않으면 출산 전 필요한 시기에 휴가를 나눠 쓰지 못해요.","steps":["유산·사산 경험, 만 40세 이상, 위험 진단서 중 해당 사유가 있는지 확인해요.","회사에 출산전후휴가 분할 사용을 청구해요."],"where":"회사(사용자)","amount":null,"eligibility":"유산·사산 경험, 청구 당시 만 40세 이상, 유산·사산 위험 진단서 제출 중 하나에 해당하는 임신 근로자예요.","timing":{"anchor":"due","from_days":null,"to_days":0,"label":"출산 전 어느 때라도 청구"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"근로기준법 제74조(임산부의 보호) 제2항","url":"https://www.law.go.kr/법령/근로기준법","checked":"2026-09-13"},{"org":"국가법령정보센터","title":"근로기준법 시행령 제43조 제1항","url":"https://www.law.go.kr/법령/근로기준법시행령","checked":"2026-09-13"}],"verified":true,"note":null},{"id":"preg-miscarriage-stillbirth-leave","stage":"preg-1","kind":"work-right","who":"엄마","title":"유산·사산휴가","summary":"유산·사산한 근로자가 청구하면 임신기간에 따라 휴가를 받아요. 15주 이내 10일, 16~21주 30일, 22~27주 60일, 28주 이상 90일까지예요. 모두 유산·사산한 날부터 세요.","loses":"청구해야 주어지는 휴가라서 모르면 연차나 결근으로 처리될 수 있어요.","steps":["휴가 청구 사유, 발생일, 임신기간을 적은 유산·사산휴가 신청서를 써요.","의료기관 진단서를 붙여 회사에 내요."],"where":"회사(사용자)","amount":null,"eligibility":"임신 중 유산 또는 사산한 여성 근로자예요. 모자보건법 제14조제1항에 해당하지 않는 인공 임신중절에 따른 유산은 제외돼요.","timing":{"anchor":"due","from_days":null,"to_days":null,"label":"유산·사산한 날부터 임신기간별 일수까지"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"근로기준법 제74조(임산부의 보호) 제3항·제4항","url":"https://www.law.go.kr/법령/근로기준법","checked":"2026-09-13"},{"org":"국가법령정보센터","title":"근로기준법 시행령 제43조(유산ㆍ사산휴가의 청구 등)","url":"https://www.law.go.kr/법령/근로기준법시행령","checked":"2026-09-13"}],"verified":true,"note":"근로기준법 제74조제4항에 따라 휴가 중 처음 60일(다태아 75일)은 유급이에요."},{"id":"preg-spouse-miscarriage-stillbirth-leave","stage":"preg-1","kind":"work-right","who":"아빠","title":"배우자 유산·사산휴가","summary":"2026년 9월 18일부터 배우자가 유산·사산하면 근로자가 5일 범위에서 휴가를 청구할 수 있어요. 처음 3일은 유급이에요.","loses":"배우자가 유산·사산한 날부터 20일 안에 청구하지 않으면 쓸 수 없어요.","steps":["배우자가 유산·사산한 날부터 20일 안에 회사에 휴가를 청구해요."],"where":"회사(사업주)","amount":null,"eligibility":"배우자가 유산 또는 사산한 근로자예요. 모자보건법 제14조제1항에 해당하지 않는 인공 임신중절에 따른 유산은 제외돼요.","timing":{"anchor":"due","from_days":null,"to_days":null,"label":"배우자가 유산·사산한 날부터 20일 이내 청구"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"남녀고용평등과 일ㆍ가정 양립 지원에 관한 법률 제18조의4(배우자 유산ㆍ사산휴가), 2026.9.18. 시행","url":"https://www.law.go.kr/법령/남녀고용평등과일ㆍ가정양립지원에관한법률","checked":"2026-09-13"},{"org":"고용노동부","title":"'아빠 육아휴직' 40% 돌파 코앞...육아휴직급여 수급자 상반기","url":"https://www.moel.go.kr/news/enews/report/enewsView.do?news_seq=19652","checked":"2026-09-13"}],"verified":true,"note":"2026.9.18. 시행 신설 조항이에요. 오늘(9.13.) 기준 아직 시행 전이에요. 신청방법은 대통령령으로 정하게 되어 있어요. 시행령 세부 내용은 확인하지 못했어요."},{"id":"preg-ultrasound-coverage-second-third-trimester","stage":"preg-2","kind":"checkup-info","who":"엄마","title":"임신 중기·후기 초음파 건강보험 급여 횟수","summary":"일반 초음파는 임신 14~19주, 20~35주, 36주 이후에 각 1회 건강보험 급여로 인정돼요. 정밀 초음파는 임신 16주 이후 1회 인정돼요. 병원마다 다를 수 있어요.","loses":"정밀 초음파는 16주 이후 1회만 급여로 인정돼요. 그 밖에 더 한 정밀 초음파는 비급여로 처리될 수 있어요.","steps":[],"where":"산부인과 의료기관","amount":"건강보험 급여(일반 3개 구간 각 1회, 16주 이후 정밀 1회)","eligibility":"단태아 기준이에요. 다태아는 제2태아부터 소정점수의 50%를 산정해요. 급여기준에 적힌 태아·모체 상태에 해당하면 횟수를 넘겨도 급여가 인정돼요.","timing":{"anchor":"due","from_days":-182,"to_days":null,"label":"통상 임신 14주 이후 구간별"},"region":"전국","sources":[{"org":"건강보험심사평가원","title":"초음파 검사의 급여기준(고시 제2023-105호, 2023.7.1. 시행)","url":"https://www.hira.or.kr/rc/insu/insuadtcrtr/InsuAdtCrtrPopup.do?mtgHmeDd=20230701&sno=1&mtgMtrRegSno=0001","checked":"2026-09-13"},{"org":"건강보험심사평가원","title":"임산부 초음파 주수별 급여 인정 횟수","url":"https://www.hira.or.kr/bbsDummy.do?pgmid=HIRAA010006011000&brdScnBltNo=4&brdBltNo=47499&pageIndex=1&pageIndex2=1","checked":"2026-09-13"}],"verified":true,"note":"고시 시행일은 2023.7.1.이에요. 2026년 이후 개정 고시가 있는지는 따로 확인하지 못했어요."},{"id":"preg-maternal-serum-screening","stage":"preg-2","kind":"checkup-info","who":"엄마","title":"삼중·사중 표지자 검사(쿼드검사)와 통합선별검사","summary":"임신부 혈액으로 다운증후군 등 염색체 이상과 신경관 결손, 복벽 결손의 위험도를 평가하는 모체 혈청 선별검사예요. 병원마다 다를 수 있어요.","steps":[],"where":"산부인과 의료기관","amount":null,"eligibility":"선별검사(확진 검사 아님). 통합선별검사 1차는 임신 11~14주에 혈액검사와 초음파를 해요. 2차는 임신 15~22주에 혈액검사를 해요.","timing":{"anchor":"due","from_days":-175,"to_days":-126,"label":"통상 임신 15~22주"},"region":"전국","sources":[{"org":"질병관리청 국가건강정보포털","title":"삼중 또는 사중 표지자 검사(Triple 또는 Quad test)와 통합선별검사 (Integrated test)","url":"https://health.kdca.go.kr/healthinfo/biz/health/gnrlzHealthInfo/gnrlzHealthInfo/gnrlzHealthInfoView.do?cntnts_sn=5515","checked":"2026-09-13"},{"org":"임신육아종합포털 아이사랑","title":"산전검사와 예방접종 > 임신중기(14~27주)","url":"https://www.childcare.go.kr/?menuno=368","checked":"2026-09-13"}],"verified":true,"note":"시행 주수가 원문끼리 달라요. 국가건강정보포털은 15~22주, 아이사랑은 15~20주로 적었어요. 넓은 쪽을 썼어요. 건강보험 급여 여부는 공식 원문에서 확인하지 못해 금액을 비워 뒀어요."},{"id":"preg-detailed-ultrasound-mid","stage":"preg-2","kind":"checkup-info","who":"엄마","title":"중기 정밀 초음파","summary":"임신 중기에 태아의 구조를 자세히 살펴보는 초음파 검사예요. 병원마다 다를 수 있어요.","steps":[],"where":"산부인과 의료기관","amount":"건강보험 급여(임신 16주 이후 정밀 초음파 1회)","eligibility":null,"timing":{"anchor":"due","from_days":-140,"to_days":-112,"label":"통상 임신 20~24주"},"region":"전국","sources":[{"org":"임신육아종합포털 아이사랑","title":"산전검사와 예방접종 > 임신중기(14~27주)","url":"https://www.childcare.go.kr/?menuno=368","checked":"2026-09-13"},{"org":"건강보험심사평가원","title":"초음파 검사의 급여기준(고시 제2023-105호)","url":"https://www.hira.or.kr/rc/insu/insuadtcrtr/InsuAdtCrtrPopup.do?mtgHmeDd=20230701&sno=1&mtgMtrRegSno=0001","checked":"2026-09-13"}],"verified":true,"note":"시행 주수는 아이사랑 산전검사 일정표 기준이에요. 급여 범위는 심평원 급여기준의 16주 이후 정밀 초음파 1회예요."},{"id":"preg-gestational-diabetes-test","stage":"preg-2","kind":"checkup-info","who":"엄마","title":"임신성 당뇨 검사","summary":"포도당을 마신 뒤 혈당을 재어 임신성 당뇨를 확인하는 검사예요. 50g 선별검사에서 기준을 넘으면 100g 검사로 진단해요. 일부 기관은 75g 검사를 해요. 병원마다 다를 수 있어요.","steps":[],"where":"산부인과 의료기관","amount":null,"eligibility":"50g 검사는 선별검사, 100g·75g 검사는 진단검사예요.","timing":{"anchor":"due","from_days":-112,"to_days":-84,"label":"통상 임신 24~28주"},"region":"전국","sources":[{"org":"대한산부인과학회","title":"임신성 당뇨","url":"https://www.ksog.org/public/index.php?sub=1&third=8","checked":"2026-09-13"},{"org":"임신육아종합포털 아이사랑","title":"산전검사와 예방접종 > 임신중기(14~27주)","url":"https://www.childcare.go.kr/?menuno=368","checked":"2026-09-13"}],"verified":true,"note":"건강보험 급여 여부는 공식 원문에서 확인하지 못해 금액을 비워 뒀어요."},{"id":"preg-spouse-risk-pregnancy-parental-leave","stage":"preg-2","kind":"work-right","who":"아빠","title":"임신 중 배우자 돌봄 육아휴직","summary":"2026년 9월 18일부터 남성 근로자도 유산, 조산 등 위험이 있는 임신 중 배우자를 돌보려고 출산 전에 육아휴직을 신청할 수 있어요.","loses":"출산 전에는 아빠 육아휴직을 못 쓴다고 알고 연차나 무급으로 버틸 수 있어요.","steps":["위험 사유가 고용노동부령 범위에 드는지 확인해요.","휴직 시작 예정일 30일 전까지 출산 예정일을 적은 육아휴직 신청서를 회사에 내요."],"where":"회사(사업주)","amount":null,"eligibility":"고용노동부령으로 정하는 유산, 조산 등 위험이 있는 임신 중 배우자를 둔 남성 근로자예요.","timing":{"anchor":"due","from_days":null,"to_days":0,"label":"임신 중, 휴직 시작 30일 전까지 신청"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"남녀고용평등과 일ㆍ가정 양립 지원에 관한 법률 제19조(육아휴직), 2026.9.18. 시행","url":"https://www.law.go.kr/법령/남녀고용평등과일ㆍ가정양립지원에관한법률","checked":"2026-09-13"},{"org":"국가법령정보센터","title":"남녀고용평등과 일ㆍ가정 양립 지원에 관한 법률 시행령 제11조","url":"https://www.law.go.kr/법령/남녀고용평등과일ㆍ가정양립지원에관한법률시행령","checked":"2026-09-13"},{"org":"고용노동부","title":"'아빠 육아휴직' 40% 돌파 코앞...육아휴직급여 수급자 상반기","url":"https://www.moel.go.kr/news/enews/report/enewsView.do?news_seq=19652","checked":"2026-09-13"}],"verified":true,"note":"2026.9.18. 시행이에요. 위험 사유의 구체 범위(고용노동부령)와 이 기간 육아휴직 급여 적용 방식은 확인하지 못했어요."},{"id":"preg-seoul-safe-postnatal-care-center","stage":"preg-2","kind":"deadline","who":"부부","title":"서울형 안심 산후조리원 사전예약","summary":"서울시가 지정한 산후조리원을 순위에 따라 지원받아 이용하는 시범사업이에요. 2026년 6월부터 2027년 5월까지 운영해요. 분만예정월 6개월 전에 온라인으로 사전예약해요.","loses":"분만예정월마다 접수일이 3일뿐이라 놓치면 그 달 출산으로는 사전예약을 신청할 수 없어요.","steps":["신청일 기준 서울 1년 이상 거주를 확인해요. 1개월 이내 발급한 주민등록 서류로 확인해요.","분만예정월 6개월 전 접수일에 서울시 공공서비스예약에서 1차 온라인 예약을 해요.","1~4순위 명단에 따라 산후조리원별 상담·접수를 한 뒤 최종 예약을 확정해요."],"where":"서울특별시 공공서비스예약(yeyak.seoul.go.kr)","amount":"13박 14일 일반실 기준 390만원 중 순위별 지원(1순위 전액, 4순위 140만원)","eligibility":"신청일 기준 서울시에 1년 이상 거주한 산모예요. 1순위는 기초생활수급·차상위예요. 2순위는 국가유공자·다문화·장애인 산모·한부모·세쌍둥이 이상·셋째아 이상이에요. 3순위는 쌍둥이·둘째아, 4순위는 그 밖의 산모예요.","timing":{"anchor":"due","from_days":null,"to_days":null,"label":"분만예정월 6개월 전 달 초 3일간(예: 2027년 4월생은 2026.9.30.~10.2., 5월생은 2026.11.2.~11.4.)"},"region":"서울","sources":[{"org":"서울시 임신·출산 정보센터","title":"서울형 안심 산후조리원이란?","url":"https://seoul-agi.seoul.go.kr/postnatal-care","checked":"2026-09-13"},{"org":"서울시 임신·출산 정보센터","title":"신청: 서울시 임신출산 정보센터(접수 일정)","url":"https://seoul-agi.seoul.go.kr/index","checked":"2026-09-13"}],"verified":true,"note":"시범사업이라 2027년 5월 이후 출산 예정자 접수는 확인하지 못했어요. from/to_days는 분만예정월 기준 일정을 예정일 기준으로 어림한 범위예요. 지정 조리원 수는 서울시 누리집 게시물마다 달라 넣지 않았어요. 시범운영 때는 4곳, 확대 후 안내 페이지에는 5곳으로 적혀 있어요. 오늘(9.13.) 기준 2027년 3월생 접수(9.1.~9.3.)는 지났어요. 예약 창이 분만예정월 기준 3일이라 날짜를 계산하지 않고 원문 표현만 보여요."},{"id":"preg-leave-schedule-with-employer","stage":"preg-2","kind":"work-right","who":"부부","title":"출산전후휴가·배우자 출산전후휴가·육아휴직 일정 상의","summary":"육아휴직은 시작 예정일 30일 전까지 신청서를 내야 해요. 출산 후 18개월 안에 육아휴직을 시작하려면 출산전후휴가를 청구하거나 배우자 출산전후휴가를 알릴 때 육아휴직을 함께 신청할 수 있어요.","loses":"함께 신청할 수 있다는 걸 모르고 따로 챙기다 보면 시작일 30일 전 신청 기한을 넘길 수 있어요. 그러면 원하는 날짜에 육아휴직을 시작하지 못할 수 있어요.","steps":["출산예정일을 기준으로 엄마 출산전후휴가, 아빠 배우자 출산전후휴가, 육아휴직 날짜의 초안을 잡아요.","각자 회사와 일정을 상의해요.","출산전후휴가를 청구하거나 배우자 출산전후휴가를 알릴 때 육아휴직 신청서를 함께 내요. 신청서에는 출산 예정일을 적어요."],"where":"각자 회사(사업주)","amount":null,"eligibility":"근로자","timing":{"anchor":"due","from_days":null,"to_days":null,"label":"각 휴가 시작 전, 육아휴직은 시작 예정일 30일 전까지 신청"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"남녀고용평등과 일ㆍ가정 양립 지원에 관한 법률 시행령 제11조(육아휴직의 신청 등)","url":"https://www.law.go.kr/법령/남녀고용평등과일ㆍ가정양립지원에관한법률시행령","checked":"2026-09-13"},{"org":"국가법령정보센터","title":"근로기준법 제74조(임산부의 보호)","url":"https://www.law.go.kr/법령/근로기준법","checked":"2026-09-13"},{"org":"국가법령정보센터","title":"남녀고용평등과 일ㆍ가정 양립 지원에 관한 법률 제18조의2·제19조","url":"https://www.law.go.kr/법령/남녀고용평등과일ㆍ가정양립지원에관한법률","checked":"2026-09-13"}],"verified":true,"note":"출산전후휴가와 배우자 출산전후휴가 자체는 법에 별도 사전 신청 기한이 없어요. 회사 규정에 따라 알리는 시점이 다를 수 있어요."},{"id":"preg-late-reduced-working-hours","stage":"preg-3","kind":"work-right","who":"엄마","title":"임신기간 근로시간 단축(임신 32주 이후)","summary":"임신 32주 이후 여성 근로자가 신청하면 회사는 하루 2시간 근로시간 단축을 허용해야 해요. 이때 임금을 깎을 수 없어요. 하루 근로시간이 8시간 미만이면 6시간이 되도록 단축할 수 있어요.","loses":"신청하지 않으면 임금 삭감 없이 하루 2시간 줄여 일할 수 있는 기간을 그냥 보내요.","steps":["임신기간, 단축 시작·종료 예정일, 근무 시작·종료 시각을 적은 문서를 써요.","의사 진단서를 붙여 단축 시작 예정일 3일 전까지 회사에 내요. 같은 임신으로 다시 신청할 때는 진단서를 붙이지 않아도 돼요."],"where":"회사(사용자)","amount":null,"eligibility":"임신 32주 이후 여성 근로자예요. 유산·조산 등 위험이 있으면 임신 전 기간이에요.","timing":{"anchor":"due","from_days":-56,"to_days":0,"label":"임신 32주부터 출산 전까지, 시작 3일 전까지 신청"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"근로기준법 제74조(임산부의 보호) 제7항·제8항(2026.8.20. 시행본)","url":"https://www.law.go.kr/법령/근로기준법","checked":"2026-09-13"},{"org":"국가법령정보센터","title":"근로기준법 시행령 제43조의2(임신기간 근로시간 단축의 신청)","url":"https://www.law.go.kr/법령/근로기준법시행령","checked":"2026-09-13"}],"verified":true,"note":"현행 조문은 임신 후 12주 이내 또는 32주 이후로 되어 있어요. 이전 기준 주수와 개정 시행일은 이번에 원문으로 확인하지 않았어요."},{"id":"preg-spouse-prenatal-postnatal-leave","stage":"preg-3","kind":"work-right","who":"아빠","title":"배우자 출산전후휴가","summary":"배우자 임신·출산 때 20일 유급휴가를 받고 3회까지 나눠 쓸 수 있어요. 2026년 9월 18일부터는 출산예정일 50일 전부터 쓸 수 있어요.","loses":"배우자가 출산한 날부터 120일이 지나면 남은 휴가를 쓸 수 없어요.","steps":["출산예정일 50일 전 이후로 쓸 날짜를 정해요. 3회까지 나눠 쓸 수 있어요.","회사에 휴가를 알려요.","우선지원대상기업이면 고용24에서 배우자 출산휴가 급여를 신청해요."],"where":"회사(사업주), 급여는 고용24","amount":null,"eligibility":"배우자가 임신·출산한 근로자. 고용보험 급여는 우선지원대상기업 근로자만 받아요.","timing":{"anchor":"due","from_days":-50,"to_days":120,"label":"출산예정일 50일 전부터 출산일 이후 120일까지","to_anchor":"birth"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"남녀고용평등과 일ㆍ가정 양립 지원에 관한 법률 제18조의2(배우자 출산전후휴가), 2026.9.18. 시행","url":"https://www.law.go.kr/법령/남녀고용평등과일ㆍ가정양립지원에관한법률","checked":"2026-09-13"},{"org":"고용노동부","title":"'아빠 육아휴직' 40% 돌파 코앞...육아휴직급여 수급자 상반기","url":"https://www.moel.go.kr/news/enews/report/enewsView.do?news_seq=19652","checked":"2026-09-13"},{"org":"국가법령정보센터","title":"고용보험법 제76조(지급 기간 등) 제1항제2호","url":"https://www.law.go.kr/법령/고용보험법","checked":"2026-09-13"}],"verified":true,"note":"to_days 120은 실제 출산일 기준이에요. 9.17.까지 시행 조문은 이름이 배우자 출산휴가이고 출산 후에만 쓸 수 있어요. 배우자 출산휴가 급여의 상한액과 9.18. 이후 고용보험법 명칭 반영 여부는 확인하지 못했어요."},{"id":"preg-maternity-leave","stage":"preg-3","kind":"work-right","who":"엄마","title":"출산전후휴가","summary":"출산 전과 후를 합쳐 90일(미숙아 출산 100일, 다태아 120일)의 휴가를 받아요. 출산 후에 45일(다태아 60일) 이상을 배정해야 해요. 처음 60일(다태아 75일)은 유급이에요.","loses":"출산 전에 휴가를 45일(다태아 60일)보다 길게 당겨 쓰면 출산 후 최소 일수를 채울 수 없어요. 그러면 휴가 배정을 다시 짜야 해요.","steps":["출산예정일을 기준으로 출산 전에 쓸 날을 정해요. 출산 후 45일 이상은 남겨요.","회사에 출산전후휴가를 청구해요."],"where":"회사(사용자)","amount":null,"eligibility":"임신 중인 여성 근로자","timing":{"anchor":"due","from_days":-45,"to_days":null,"label":"단태아는 출산 전 최대 45일부터, 출산 후 45일 이상 사용"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"근로기준법 제74조(임산부의 보호) 제1항·제4항","url":"https://www.law.go.kr/법령/근로기준법","checked":"2026-09-13"}],"verified":true,"note":"from_days -45는 90일 중 출산 후 45일을 뺀 단태아 기준 최대치예요. 다태아는 -60이에요. 미숙아 범위는 고용노동부령으로 정해요."},{"id":"preg-postpartum-helper-voucher","stage":"preg-3","kind":"deadline","who":"엄마","title":"산모·신생아 건강관리 지원","summary":"산모·신생아 건강관리사가 출산가정을 방문해 산후관리를 돕는 바우처예요. 서비스 기간은 단태아 5~20일, 쌍태아 10~20일, 삼태아 이상 15~40일이에요. 출산일로부터 90일 안에 써요.","loses":"출산일로부터 60일이 지나면 신청할 수 없어 정부지원금을 받지 못해요.","steps":["출산예정일 40일 전부터 신청해요.","복지로에서 온라인으로 신청하거나 산모 주민등록지 보건소에 방문해 신청해요.","바우처가 결정되면 제공기관을 골라 서비스를 이용해요."],"where":"복지로(www.bokjiro.go.kr) 또는 산모 주민등록지 관할 보건소","amount":"서비스 가격에서 정부지원금을 뺀 차액을 본인이 부담해요(유형·기간별로 달라요)","eligibility":"기준중위소득 150% 이하 출산가정이에요. 산모와 배우자 등 가구의 건강보험료 본인부담금 합산액으로 판단해요. 쌍생아 이상, 둘째아 이상, 장애인 산모, 희귀질환 산모 등은 소득 기준을 넘어도 예외로 지원해요.","timing":{"anchor":"due","from_days":-40,"to_days":60,"label":"출산예정일 40일 전부터 출산일로부터 60일까지 신청","to_anchor":"birth"},"region":"전국","sources":[{"org":"사회서비스 전자바우처","title":"사업별소개 > 산모/신생아건강관리지원사업","url":"https://www.socialservice.or.kr:444/user/htmlEditor/view2.do?p_sn=7","checked":"2026-09-13"},{"org":"서울시 임신·출산 정보센터","title":"산모·신생아 건강관리 서비스 지원사업","url":"https://seoul-agi.seoul.go.kr/health-support","checked":"2026-09-13"}],"verified":true,"note":"to_days 60은 실제 출산일 기준이에요. 유산·사산은 확인일부터 30일, 미숙아 입원은 퇴원일부터 30일 이내 신청이에요. 본인부담금 표는 해마다 바뀌어 넣지 않았어요. 복지로 옛 뉴스 게시물에는 출산 후 30일로 적혀 있어 현행 안내(60일)와 달라요."},{"id":"preg-maternity-leave-pay","stage":"preg-3","kind":"deadline","who":"엄마","title":"출산전후휴가 급여(고용보험)","summary":"고용보험에서 출산전후휴가 기간의 통상임금을 지급해요. 2026년 상한은 30일 기준 220만원이에요. 대규모기업은 60일(다태아 75일)을 넘는 기간만 지원해요.","loses":"휴가가 끝난 날부터 12개월이 지나면 급여를 신청할 수 없어요.","steps":["휴가 시작 후 1개월이 지나면 신청할 수 있어요.","회사가 출산전후휴가 확인서를 내요.","고용24에서 급여를 신청해요."],"where":"고용24 또는 거주지·사업장 관할 고용센터","amount":"통상임금 100%, 상한 30일 기준 220만원(90일 660만원, 미숙아 100일 7,333,330원, 다태아 120일 880만원)","eligibility":"휴가 끝난 날 이전에 고용보험 피보험 단위기간이 180일 이상이어야 해요. 우선지원대상기업은 휴가 전체를 지원해요. 대규모기업은 60일(다태아 75일)을 넘는 기간을 지원해요. 이 기간은 30일, 미숙아 40일, 다태아 45일이 한도예요.","timing":{"anchor":"due","from_days":null,"to_days":null,"label":"휴가 시작 1개월 뒤부터 휴가 끝난 날 이후 12개월 이내 신청"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"고용보험법 제75조(출산전후휴가 급여 등)·제76조(지급 기간 등)","url":"https://www.law.go.kr/법령/고용보험법","checked":"2026-09-13"},{"org":"찾기쉬운 생활법령정보(법제처)","title":"출산전후휴가 급여의 지급 금액 및 지급 제한","url":"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&csmSeq=1379&ccfNo=3&cciNo=1&cnpClsNo=3","checked":"2026-09-13"},{"org":"고용노동부","title":"출산전후휴가 급여등 상한액 고시(고시 제2025-124호)","url":"https://www.moel.go.kr/info/lawinfo/instruction/view.do?bbs_seq=20251201736","checked":"2026-09-13"}],"verified":true,"note":"상한액은 매년 고용노동부 고시로 바뀌어요. 220만원은 생활법령정보(2026.8.15. 기준) 수치예요. 고용노동부 고시 원문은 첨부파일(HWP)이라 본문 수치를 직접 열어 보지 못했어요. 대위신청 등 회사가 대신 신청하는 경우도 있어요."},{"id":"preg-birth-registration-prep","stage":"preg-3","kind":"deadline","who":"부부","title":"출생신고 준비","summary":"출생신고는 출생 후 1개월 안에 해야 하고, 의사나 조산사가 작성한 출생증명서를 붙여야 해요. 대법원 전자가족관계등록시스템이나 정부24에서 온라인으로도 할 수 있어요.","loses":"1개월을 넘기면 5만원 이하 과태료가 붙어요. 출생신고가 있어야 신청하는 서울형 산후조리경비 같은 지원도 늦어져요.","steps":["분만 병원에서 출생증명서를 발급받아요.","신고인 신분증과 부모 혼인관계증명서를 준비해요. 혼인관계증명서는 행정정보 공동이용 때 생략할 수 있어요.","주민센터에 방문하거나 온라인으로 출생 후 1개월 안에 신고해요."],"where":"주민센터(시·구·읍·면사무소), 대법원 전자가족관계등록시스템, 정부24","amount":null,"eligibility":"혼인 중 출생자는 부 또는 모가 신고해요.","timing":{"anchor":"due","from_days":null,"to_days":null,"label":"출생 후 1개월 이내 신고"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"가족관계의 등록 등에 관한 법률 제44조·제46조·제122조","url":"https://www.law.go.kr/법령/가족관계의등록등에관한법률","checked":"2026-09-13"},{"org":"찾기쉬운 생활법령정보(법제처)","title":"출생신고하기 > 출생신고방법","url":"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&csmSeq=707&ccfNo=2&cciNo=1&cnpClsNo=1","checked":"2026-09-13"},{"org":"동대문구 보건소","title":"서울형 산후조리경비 지원사업","url":"https://www.ddm.go.kr/health/contents.do?key=3361","checked":"2026-09-13"}],"verified":true,"note":"from/to_days는 실제 출생일 기준이에요. 늦어진 기간별 과태료 금액은 원문으로 확인하지 않아 상한(5만원 이하)만 적었어요."},{"id":"baby0-birth-registration","stage":"baby-0","kind":"deadline","who":"부부","title":"출생신고","summary":"아이가 태어나면 출생 후 1개월 이내에 출생신고를 해요. 혼인 중 출생자는 부 또는 모가 신고해요.","loses":"정당한 사유 없이 1개월을 넘기면 5만원 이하의 과태료를 물어요.","steps":["병원에서 출생증명서를 받아요","시(구)·읍·면 사무소나 주민센터에 출생신고서를 내요","이때 행복출산 원스톱 서비스로 수당·바우처를 함께 신청해요"],"where":"출생지, 출생자의 등록기준지, 신고인의 주소지 또는 현재지의 시(구)·읍·면 사무소","amount":null,"eligibility":"혼인 중 출생자는 부 또는 모, 혼인 외 출생자는 모가 신고의무자예요","timing":{"anchor":"birth","from_days":0,"to_days":30,"label":"출생 후 1개월 이내"},"region":"전국","sources":[{"org":"법제처 찾기쉬운 생활법령정보","title":"가족관계 등록 > 출생 관련 신고 > 출생신고하기 > 출생신고방법","url":"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&csmSeq=707&ccfNo=2&cciNo=1&cnpClsNo=1","checked":"2026-09-13"}],"verified":true,"note":"근거는 가족관계의 등록 등에 관한 법률 제44조제1항, 제122조예요. 원문 기준일은 2026-08-15예요."},{"id":"baby0-happy-birth-onestop","stage":"baby-0","kind":"tip","who":"부부","title":"행복출산 원스톱 서비스","summary":"출생신고 때 한 번에 여러 출산 지원을 신청하는 통합 신청이에요. 부모급여, 첫만남 이용권, 아동수당, 출산가구 전기료 경감, 저소득층 기저귀·조제분유 지원 등이 들어 있어요.","loses":"따로따로 신청하다 부모급여·아동수당의 출생 후 60일 소급 기한을 넘기면 출생월부터 받지 못해요.","steps":["정부24에서 인증서로 로그인하거나 출생자 주소지 주민센터를 방문해요","행복출산 신청서에서 받을 서비스를 골라요","주민센터 확인과 접수를 거쳐 처리돼요"],"where":"정부24(gov.kr) 또는 출생자 주소지 읍·면·동 주민센터","amount":null,"eligibility":"출산자(산모) 본인 또는 배우자","timing":{"anchor":"birth","from_days":0,"to_days":30,"label":"출생신고 할 때 함께"},"region":"전국","sources":[{"org":"행정안전부 정부24","title":"행복출산 | 원스톱/생애주기/꾸러미 서비스","url":"https://www.gov.kr/portal/onestopSvc/happyBirth","checked":"2026-09-13"}],"verified":true,"note":"지자체 서비스(출산지원금, 출산용품 등)는 시도·시군구마다 달라요."},{"id":"baby0-parent-pay","stage":"baby-0","kind":"benefit","who":"부부","title":"부모급여","summary":"0세 아이를 키우는 가정에 매달 현금을 지급해요. 어린이집을 이용하면 보육료를 뺀 차액을 받아요.","loses":"출생일로부터 60일이 지나 신청하면 신청한 달부터 받아요. 출생월까지 거슬러 받지 못해요.","steps":["출생신고 때 행복출산 원스톱 서비스로 함께 신청하거나","복지로·정부24에서 온라인으로 신청하거나","읍·면·동 행정복지센터를 방문해 신청해요"],"where":"복지로, 정부24, 전국 읍·면·동 행정복지센터","amount":"0세 월 100만원(어린이집 이용 시 0세 차액 41만 6천원), 1세 월 50만원","eligibility":"0~23개월 아동","timing":{"anchor":"birth","from_days":0,"to_days":59,"label":"출생일로부터 60일 이내 신청 시 출생 월부터 소급"},"region":"전국","sources":[{"org":"문화체육관광부 대한민국 정책브리핑","title":"2026년 부모급여, 이렇게 지원합니다!","url":"https://www.korea.kr/multi/visualNewsView.do?newsId=148957936","checked":"2026-09-13"}],"verified":true,"note":"금액은 2026-01-14 게시 기준이에요. 가정양육은 매월 25일, 어린이집 이용은 다음 달 20일에 지급돼요. 60일 계산에 출생일이 들어가는지 원문에서 확정하지 못했어요. 그래서 기한을 하루 이르게 잡았어요."},{"id":"baby0-child-allowance","stage":"baby-0","kind":"benefit","who":"부부","title":"아동수당","summary":"만 9세 미만 아동에게 매달 지급해요. 수도권 거주 가정은 월 10만원이에요.","loses":"출생 후 60일이 지나 신청하면 신청한 달부터 받아요. 출생월까지 거슬러 받지 못해요.","steps":["출생신고 때 행복출산 원스톱 서비스로 함께 신청하거나","복지로·정부24에서 온라인으로 신청하거나","주민센터를 방문해 신청해요"],"where":"복지로, 정부24, 주민센터","amount":"수도권 월 10만원","eligibility":"2026년 기준 만 9세 미만 아동","timing":{"anchor":"birth","from_days":0,"to_days":59,"label":"출생 후 60일 이내 신청 시 출생월부터 소급"},"region":"전국","sources":[{"org":"문화체육관광부 대한민국 정책브리핑","title":"월 최대 13만 원…초등학생까지 확대된 아동수당, 신청 방법 확인!","url":"https://www.korea.kr/news/customizedNewsView.do?newsId=148963801","checked":"2026-09-13"},{"org":"보건복지부","title":"아동수당 대상·금액 확대, 4월부터 지급 시작","url":"https://mohw.go.kr/board.es?act=view&bid=0027&list_no=1490257&mid=a10503010100&nPage=1&tag=","checked":"2026-09-13"}],"verified":true,"note":"2026년에 대상이 만 9세 미만으로 넓어졌어요. 2030년 만 13세 미만까지 해마다 1세씩 늘어요. 비수도권·인구감소지역은 금액이 더 많아요. 60일 계산에 출생일이 들어가는지 원문에서 확정하지 못했어요. 그래서 기한을 하루 이르게 잡았어요."},{"id":"baby0-first-meeting-voucher","stage":"baby-0","kind":"benefit","who":"부부","title":"첫만남이용권","summary":"출생신고 후 주민등록번호를 받은 아이에게 국민행복카드 바우처로 한 번 지급해요. 유흥업종, 사행업종, 마사지 등 위생업종(이미용실 제외), 레저업종, 성인용품 등 기타업종, 면세점에서는 쓸 수 없어요.","loses":"출생일로부터 2년이 지나면 이용권을 쓸 수 없어요.","steps":["출생신고 때 행복출산 원스톱 서비스로 함께 신청하거나","복지로·정부24 또는 아동 주소지 주민센터에서 신청해요","국민행복카드로 포인트를 받아 써요"],"where":"아동 주민등록상 주소지 주민센터, 복지로, 정부24","amount":"첫째 200만원, 둘째 이상 300만원","eligibility":"출생신고 후 주민등록번호를 받은 아동이에요. 금액은 2024년 1월 1일 이후 출생아 기준이에요","timing":{"anchor":"birth","from_days":0,"to_days":720,"label":"출생일로부터 2년까지 사용(2024년 1월 1일 이후 출생아)"},"region":"전국","sources":[{"org":"보건복지부","title":"임신·출산 지원","url":"https://www.mohw.go.kr/menu.es?mid=a10711020100","checked":"2026-09-13"},{"org":"서울특별시 탄생육아 몽땅정보통","title":"첫만남이용권","url":"https://umppa.seoul.go.kr/hmpg/sprt/bzin/bzmgComtDetail.do?biz_mng_no=F6D62A7DF2084A88AA46833B3D7ED585","checked":"2026-09-13"},{"org":"행정안전부 정부24","title":"첫만남이용권 지원","url":"https://www.gov.kr/portal/service/serviceInfo/135200005015","checked":"2026-09-13"}],"verified":true,"note":"신청 기한은 원문끼리 달라요. 정부24 지원대상 문구는 생년월일로부터 1년이 넘지 않는 출생아예요. 같은 페이지의 사용 문구와 보건복지부는 2년 안에 신청·사용이에요. 출생 후 1년 안에 신청하면 두 기준을 모두 맞춰요."},{"id":"baby0-nhis-dependent","stage":"baby-0","kind":"deadline","who":"부부","title":"건강보험 피부양자 자격취득 신고","summary":"직장가입자인 부모 밑에 아이를 피부양자로 올리는 신고예요. 국내에서 태어난 신생아는 출생일이 자격취득일이 돼요.","loses":"사유발생일로부터 90일을 넘겨 신고하면 신고일이 자격취득일이 돼요.","steps":["직장가입자 쪽에서 피부양자 자격취득 신고서를 준비해요","국민건강보험 누리집·앱(인증서 로그인), 방문, 팩스·우편, 1577-1000 중 하나로 신고해요"],"where":"국민건강보험공단(누리집, 앱, 지사, 1577-1000)","amount":null,"eligibility":"직장가입자의 피부양자 요건을 갖춘 자녀예요","timing":{"anchor":"birth","from_days":0,"to_days":90,"label":"자격변동일(사유발생일)로부터 90일 이내"},"region":"전국","sources":[{"org":"국민건강보험공단","title":"피부양자 자격취득","url":"https://www.nhis.or.kr/nhis/minwon/wbhapa01000m01.do?mode=view&articleNo=10946887","checked":"2026-09-13"}],"verified":true,"note":"사업장 지연신고처럼 본인 책임이 없는 부득이한 사유는 지난 날짜로 거슬러 인정돼요. 출생신고만으로 자동 등록되는지는 원문 요약으로만 확인했어요. 가입자 쪽에서 등록 여부를 한 번 조회해 두면 좋아요."},{"id":"baby0-postpartum-helper-deadline","stage":"baby-0","kind":"deadline","who":"부부","title":"산모·신생아 건강관리 지원 신청 기한","summary":"출산 가정에 건강관리사를 보내는 바우처예요. 출산 후에도 정해진 날까지 신청할 수 있어요.","loses":"출산일로부터 60일이 지나면 신청할 수 없어요.","steps":["주소지 보건소나 복지로에서 신청해요","결정되면 출산일로부터 90일 안에 서비스를 써요"],"where":"주소지 보건소, 복지로","amount":null,"eligibility":null,"timing":{"anchor":"birth","from_days":0,"to_days":60,"label":"출산 예정일 40일 전부터 출산일로부터 60일까지"},"region":"전국","sources":[{"org":"보건복지부","title":"임신·출산 지원","url":"https://www.mohw.go.kr/menu.es?mid=a10711020100","checked":"2026-09-13"}],"verified":true,"note":"소득 기준과 본인부담금은 이번에 원문으로 확인하지 못했어요. 서비스 유효기간은 출산일로부터 90일(입원 시 퇴원일로부터 90일)이에요."},{"id":"baby0-diaper-formula","stage":"baby-0","kind":"benefit","who":"부부","title":"저소득층 기저귀·조제분유 지원","summary":"만 2세 미만 영아를 둔 저소득 가구에 기저귀·조제분유 구매비를 국민행복카드 바우처로 줘요.","loses":"출생일로부터 60일이 지나 신청하면 신청일 기준으로만 지원돼요.","steps":["출생신고 때 행복출산 원스톱 서비스로 함께 신청하거나","영아 주소지 보건소·주민센터 또는 복지로에서 신청해요"],"where":"영아 주민등록 주소지 시군구 보건소, 읍면동 주민센터, 복지로","amount":"기저귀 월 9만원, 조제분유 월 11만원","eligibility":"만 2세 미만 영아를 둔 기초생활보장, 차상위계층, 한부모가족 수급 가구예요. 기준중위소득 80% 이하 다자녀(2인 이상)·장애인 가구도 대상이에요","timing":{"anchor":"birth","from_days":0,"to_days":59,"label":"출생일로부터 60일 이내(출생일 포함) 신청 시 24개월 모두 지원"},"region":"전국","sources":[{"org":"행정안전부 정부24","title":"저소득층 기저귀·조제분유 지원","url":"https://www.gov.kr/portal/service/serviceInfo/WII000000500","checked":"2026-09-13"},{"org":"보건복지부","title":"임신·출산 지원","url":"https://www.mohw.go.kr/menu.es?mid=a10711020100","checked":"2026-09-13"}],"verified":true,"note":"정부24 최종 수정일 2025-11-28 기준이에요. 조제분유는 기저귀 대상 중 산모 사망·질병 등 추가 요건이 있어요."},{"id":"baby0-seoul-postpartum-care","stage":"baby-0","kind":"benefit","who":"엄마","title":"서울형 산후조리경비 지원","summary":"서울에 사는 산모에게 산후조리 비용을 바우처로 줘요. 산모·신생아 건강관리, 의약품·건강식품, 한약조제, 산후운동, 심리상담에 쓸 수 있어요.","loses":"출산일로부터 180일이 지나면 신청할 수 없어요.","steps":["서울시에 출생신고를 해요","탄생육아 몽땅정보통에서 온라인으로 신청하거나 구청을 방문해요","출산일로부터 1년 되는 달 말일까지 써요"],"where":"탄생육아 몽땅정보통(umppa.seoul.go.kr)","amount":"첫째 100만원, 둘째 120만원, 셋째 이상 150만원","eligibility":"산모와 출생자녀가 서울에 살고 서울시에 출생신고한 경우예요","timing":{"anchor":"birth","from_days":0,"to_days":180,"label":"출산일로부터 180일(6개월) 이내"},"region":"서울","sources":[{"org":"서울특별시 임신·출산 정보센터","title":"서울형 산후조리경비 지원","url":"https://seoul-agi.seoul.go.kr/postpartum-care","checked":"2026-09-13"}],"verified":true,"note":"2026-01-02부터 신청처가 서울맘케어에서 탄생육아 몽땅정보통으로 바뀌었어요. 미숙아 등 신생아가 입원했다가 퇴원한 경우는 퇴원 후 180일 이내예요."},{"id":"baby0-seoul-birth-housing","stage":"baby-0","kind":"housing","who":"부부","title":"자녀출산 무주택가구 주거비 지원","summary":"서울에 사는 무주택 출산가구에 주거비를 2년간 매달 지원해요.","loses":"출산 후 1년이 지나면 신청할 수 없어요.","steps":["소득·전월세 요건을 확인해요","신청 기간(하반기 7월 1일~12월 31일)에 탄생육아 몽땅정보통에서 온라인으로 신청해요"],"where":"탄생육아 몽땅정보통(umppa.seoul.go.kr)","amount":"월 최대 30만원(2년 720만원)","eligibility":"2025년 1월 1일 이후 출산한 서울 거주 무주택 가구예요. 자녀를 서울시에 출생신고하고 기준중위소득 180% 이하여야 해요. 집은 전세보증금 5억원 이하 또는 월세(환산액 포함) 229만원 이하여야 해요","timing":{"anchor":"birth","from_days":0,"to_days":360,"label":"출산 후 1년 이내"},"region":"서울","sources":[{"org":"서울특별시 내 손안에 서울","title":"'2년간 최대 720만 원' 무주택 출산가구 주거비 지원…신청 방법은?","url":"https://mediahub.seoul.go.kr/archives/2018691","checked":"2026-09-13"}],"verified":true,"note":"2026-07-08 게시 기준이에요. 신청은 반기마다 정한 기간에만 받아요. 출산 후 1년 안에 열리는 신청 기간을 확인해야 해요."},{"id":"baby0-seoul-parents-taxi","stage":"baby-0","kind":"benefit","who":"부부","title":"서울 엄마아빠택시","summary":"서울에 사는 24개월 이하 영아 양육자에게 영아용 카시트가 있는 택시 이용 포인트를 줘요.","loses":"신청월 기준 아이가 24개월을 넘기면 신청할 수 없어요.","steps":["몽땅정보 만능키에서 신청해요","운영업체(타다, 파파) 중 하나를 골라요"],"where":"몽땅정보 만능키(서울시)","amount":"연 10만원(영아 1인당)","eligibility":"서울시에 주소를 둔 24개월 이하 영아를 양육하는 실질적 양육자(2023년 1월생부터)","timing":{"anchor":"birth","from_days":0,"to_days":720,"label":"신청월 기준 24개월 이하"},"region":"서울","sources":[{"org":"서울특별시 임신·출산 정보센터","title":"서울 엄마아빠택시 지원","url":"https://seoul-agi.seoul.go.kr/parents-taxi","checked":"2026-09-13"}],"verified":true,"note":"포인트 사용 기한은 원문에서 확인하지 못했어요."},{"id":"baby0-newborn-special-loan","stage":"baby-0","kind":"housing","who":"부부","title":"신생아 특례 디딤돌대출·버팀목전세자금대출","summary":"출산 가구에 주택구입자금(디딤돌)과 전세자금(버팀목)을 낮은 금리로 빌려줘요.","loses":"대출접수일 기준으로 출산 후 2년이 지나면 신생아 특례 대상에서 빠져요.","steps":["주택도시기금 누리집에서 소득·자산 요건을 확인해요","수탁은행이나 기금e든든에서 대출을 접수해요"],"where":"주택도시기금(nhuf.molit.go.kr) 및 수탁은행","amount":"디딤돌 최대 4억원(금리 1.8%~4.5%), 버팀목 최대 2.4억원(임차보증금의 80% 이내, 금리 1.3%~4.3%)","eligibility":"대출접수일 기준 2년 내에 출산한('23.1.1. 이후 출생아) 무주택 세대주예요. 디딤돌은 1주택 대환도 포함해요. 부부합산 연소득 1.3억원 이하(맞벌이 2억원 이하)여야 해요. 순자산은 디딤돌 5.11억원·버팀목 3.45억원 이하여야 해요","timing":{"anchor":"birth","from_days":0,"to_days":720,"label":"대출접수일 기준 2년 내 출산"},"region":"전국","sources":[{"org":"국토교통부 주택도시기금","title":"개인상품 전체보기","url":"https://nhuf.molit.go.kr/FP/FP05/FP0501/FP0501.jsp","checked":"2026-09-13"},{"org":"국토교통부 주택도시기금","title":"자주하는 질문 < 신생아 특례 디딤돌대출","url":"https://nhuf.molit.go.kr/FP/FP05/FP0503/FP05030807.jsp?gotoPage=3","checked":"2026-09-13"}],"verified":true,"note":"금리와 순자산 기준은 해마다 바뀌어요. 버팀목 순자산 기준이 검색 요약에서는 3.37억원으로 나와 누리집 표기(3.45억원)와 달랐어요. 수도권 LTV는 70%예요."},{"id":"baby0-electricity-discount","stage":"baby-0","kind":"benefit","who":"부부","title":"출산가구 전기요금 할인","summary":"출생일로부터 3년 미만 영아가 있는 가구의 주택용 전기요금을 깎아 줘요. 신청 후 3년까지 적용돼요.","loses":"신청하지 않으면 할인이 적용되지 않아요.","steps":["행복출산 원스톱 서비스로 함께 신청하거나","한전ON, 국번 없이 123, 한전 사업소·행정복지센터에서 신청해요"],"where":"한국전력공사(한전ON, 123), 행정복지센터","amount":"해당월 전기요금 30% 할인(월 16,000원 한도)","eligibility":"출생일로부터 3년 미만 영아가 1명 이상 있는 주택용 가구예요","timing":{"anchor":"birth","from_days":0,"to_days":1080,"label":"출생일로부터 3년 미만"},"region":"전국","sources":[{"org":"행정안전부 정부24 보조금24","title":"전기 요금 복지할인","url":"https://www.gov.kr/portal/rcvfvrSvc/dtlEx/B41000200003","checked":"2026-09-13"},{"org":"문화체육관광부 대한민국 정책브리핑","title":"[오맞! 이 정책] 대가족·다자녀·출산가구 \"전기요금 30% 할인 받으세요~\"","url":"https://www.korea.kr/news/policyNewsView.do?newsId=148885177","checked":"2026-09-13"}],"verified":true,"note":"할인율·한도는 정부24(2026-08-14 수정) 기준이에요. 3년 미만 연령 조건은 2021년 정책브리핑에서만 확인했어요. 지난 달 요금 소급 여부는 확인하지 못했어요."},{"id":"baby0-birth-tax-credit","stage":"baby-0","kind":"benefit","who":"부부","title":"출산·입양 세액공제","summary":"아이가 태어난 해의 연말정산에서 출생 순서에 따라 세금을 깎아 줘요.","loses":"출생한 해 연말정산에서 아이를 공제대상자녀로 올리지 않으면 이 공제를 받지 못해요.","steps":["부부 중 누가 아이를 부양가족으로 올릴지 정해요","출생한 해 귀속 연말정산에서 공제대상자녀로 신고해요"],"where":"회사 연말정산(국세청 홈택스)","amount":"첫째 연 30만원, 둘째 연 50만원, 셋째 이상 연 70만원","eligibility":"해당 과세기간에 출산하거나 입양 신고한 공제대상자녀","timing":{"anchor":"birth","from_days":0,"to_days":null,"label":"출생한 해 귀속 연말정산"},"region":"전국","sources":[{"org":"법제처 찾기쉬운 생활법령정보","title":"저출생 지원 > 그 밖의 지원 > 세제혜택 및 출산 크레딧 > 세액공제 및 비과세 혜택","url":"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&csmSeq=2604&ccfNo=4&cciNo=1&cnpClsNo=1","checked":"2026-09-13"}],"verified":true,"note":"근거는 소득세법 제59조의2예요. 자녀세액공제는 0세에 해당하지 않아 넣지 않았어요."},{"id":"baby0-employer-birth-bonus-taxfree","stage":"baby-0","kind":"benefit","who":"부부","title":"출산지원금 비과세","summary":"회사에서 받는 출산지원금은 자녀 출생일 이후 2년 이내에 첫 번째와 두 번째로 받는 금액 전액이 비과세예요.","loses":"출생일 이후 2년이 지나 받거나 세 번째 이후로 받는 금액은 이 비과세를 받지 못해요.","steps":["회사 출산지원금 지급 규정과 지급 시기를 확인해요","출생일 이후 2년 안에 지급받도록 회사와 일정을 맞춰요"],"where":"근무하는 회사(급여 담당)","amount":"출생일 이후 2년 이내 첫 번째·두 번째 지급분 전액","eligibility":"2021년 1월 1일 이후 출생한 자녀에 대해 사용자로부터 받는 출산지원금","timing":{"anchor":"birth","from_days":0,"to_days":720,"label":"자녀의 출생일 이후 2년 이내"},"region":"전국","sources":[{"org":"법제처 찾기쉬운 생활법령정보","title":"저출생 지원 > 그 밖의 지원 > 세제혜택 및 출산 크레딧 > 세액공제 및 비과세 혜택","url":"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&csmSeq=2604&ccfNo=4&cciNo=1&cnpClsNo=1","checked":"2026-09-13"}],"verified":true,"note":"근거는 소득세법 제12조제3호머목이에요. 회사가 출산지원금을 주지 않으면 해당이 없어요."},{"id":"baby0-spouse-leave-deadline","stage":"baby-0","kind":"work-right","who":"아빠","title":"배우자 출산휴가 사용 기한","summary":"배우자 출산휴가 20일(유급)은 출산일부터 정해진 기간 안에만 청구할 수 있어요. 3회까지 나눠 쓸 수 있어요.","loses":"배우자가 출산한 날부터 120일이 지나면 남은 휴가를 청구할 수 없어요.","steps":["나눠 쓸 일정을 정해요(최대 3회)","회사에 휴가를 청구해요"],"where":"근무하는 회사","amount":null,"eligibility":"배우자가 출산한 근로자","timing":{"anchor":"birth","from_days":0,"to_days":120,"label":"배우자가 출산한 날부터 120일 이내"},"region":"전국","sources":[{"org":"법제처 찾기쉬운 생활법령정보","title":"일과 가정생활 > 배우자 출산휴가 > 배우자 출산휴가 신청","url":"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&csmSeq=1380&ccfNo=1&cciNo=2&cnpClsNo=1","checked":"2026-09-13"}],"verified":true,"note":"근거는 남녀고용평등과 일·가정 양립 지원에 관한 법률 제18조의2예요. 원문 기준일은 2026-08-15예요."},{"id":"baby0-vaccine-birth-1month","stage":"baby-0","kind":"vaccine","who":"부부","title":"출생 ~ 생후 1개월 무렵 접종 묶음","summary":"표준예방접종일정표(2026)에서 이 시기에 있는 국가예방접종은 B형간염 1차(출생시), 결핵 1차(4주이내), B형간염 2차(1개월)예요. 위탁의료기관과 보건소에서 비용부담 없이 받을 수 있어요. 개인 일정은 의료기관과 상의해요.","loses":"위탁의료기관 밖에서 접종하면 예방접종 비용을 지원받을 수 없어요.","steps":["예방접종도우미에서 위탁의료기관을 찾아요","접종 후 예방접종도우미에서 기록을 확인해요"],"where":"위탁의료기관, 보건소(예방접종도우미 nip.kdca.go.kr에서 검색)","amount":"국가예방접종 비용부담 없음","eligibility":"12세 이하 어린이(2026년도 기준 2013.1.1. 이후 출생자)","timing":{"anchor":"birth","from_days":0,"to_days":59,"label":"출생시, 4주이내, 1개월"},"region":"전국","sources":[{"org":"질병관리청 예방접종도우미","title":"표준예방접종일정표(2026)","url":"https://nip.kdca.go.kr/irhp/infm/goImgPopup.do?num=1","checked":"2026-09-13"},{"org":"질병관리청 예방접종도우미","title":"국가예방접종사업","url":"https://nip.kdca.go.kr/irhp/infm/goVcntInfo.do?menuLv=1&menuCd=131","checked":"2026-09-13"}],"verified":true,"note":"일정표는 이미지로만 제공돼 이미지를 직접 읽었어요. 일정표는 감염병 이름으로 적혀 있어요."},{"id":"baby0-checkup-1","stage":"baby-0","kind":"screening","who":"부부","title":"영유아 건강검진 1차","summary":"영유아 건강검진 1차의 검진 시기는 생후 14~35일이에요. 건강보험가입자는 공단이 전액 부담해 본인부담이 없어요. 개인 일정은 의료기관과 상의해요.","steps":["국민건강보험 누리집 영유아 검진대상 조회에서 검진기관을 찾아요","검진 시기 안에 예약하고 문진표를 준비해요"],"where":"전국 영유아 검진기관(국민건강보험 누리집에서 조회)","amount":"본인부담 없음","eligibility":"생후 14일부터 71개월까지의 영유아","timing":{"anchor":"birth","from_days":14,"to_days":35,"label":"생후 14~35일"},"region":"전국","sources":[{"org":"국민건강보험공단","title":"영유아 건강검진 안내","url":"https://www.nhis.or.kr/nhis/healthin/wbhaca04800m01.do","checked":"2026-09-13"}],"verified":true,"note":"검진 시기를 넘겼을 때의 처리는 원문에서 확인하지 못했어요."},{"id":"baby0-vaccine-2months","stage":"baby-0","kind":"vaccine","who":"부부","title":"생후 2개월 무렵 접종 묶음","summary":"표준예방접종일정표(2026)에서 2개월에 있는 국가예방접종은 디프테리아 파상풍 백일해 1차, 폴리오 1차, b형헤모필루스인플루엔자 1차예요. 폐렴구균 감염증 1차, 로타바이러스 감염증 1차(RV1 또는 RV5)도 있어요. 위탁의료기관과 보건소에서 비용부담 없이 받을 수 있어요. 개인 일정은 의료기관과 상의해요.","loses":"위탁의료기관 밖에서 접종하면 예방접종 비용을 지원받을 수 없어요.","steps":["예방접종도우미에서 위탁의료기관을 찾아요","접종 후 예방접종도우미에서 기록을 확인해요"],"where":"위탁의료기관, 보건소(예방접종도우미 nip.kdca.go.kr에서 검색)","amount":"국가예방접종 비용부담 없음","eligibility":"12세 이하 어린이(2026년도 기준 2013.1.1. 이후 출생자)","timing":{"anchor":"birth","from_days":60,"to_days":119,"label":"2개월"},"region":"전국","sources":[{"org":"질병관리청 예방접종도우미","title":"표준예방접종일정표(2026)","url":"https://nip.kdca.go.kr/irhp/infm/goImgPopup.do?num=1","checked":"2026-09-13"},{"org":"질병관리청 예방접종도우미","title":"국가예방접종사업","url":"https://nip.kdca.go.kr/irhp/infm/goVcntInfo.do?menuLv=1&menuCd=131","checked":"2026-09-13"}],"verified":true,"note":"디프테리아 파상풍 백일해, 폴리오, b형헤모필루스인플루엔자는 일정표에서 혼합백신으로 묶여 있어요. 로타바이러스는 RV1(2회)과 RV5(3회) 두 종류가 있어요."},{"id":"baby0-vaccine-4months","stage":"baby-0","kind":"vaccine","who":"부부","title":"생후 4개월 무렵 접종 묶음","summary":"표준예방접종일정표(2026)에서 4개월에 있는 국가예방접종은 디프테리아 파상풍 백일해 2차, 폴리오 2차, b형헤모필루스인플루엔자 2차예요. 폐렴구균 감염증 2차, 로타바이러스 감염증 2차(RV1은 접종완료, RV5)도 있어요. 위탁의료기관과 보건소에서 비용부담 없이 받을 수 있어요. 개인 일정은 의료기관과 상의해요.","loses":"위탁의료기관 밖에서 접종하면 예방접종 비용을 지원받을 수 없어요.","steps":["예방접종도우미에서 위탁의료기관을 찾아요","접종 후 예방접종도우미에서 기록을 확인해요"],"where":"위탁의료기관, 보건소(예방접종도우미 nip.kdca.go.kr에서 검색)","amount":"국가예방접종 비용부담 없음","eligibility":"12세 이하 어린이(2026년도 기준 2013.1.1. 이후 출생자)","timing":{"anchor":"birth","from_days":120,"to_days":179,"label":"4개월"},"region":"전국","sources":[{"org":"질병관리청 예방접종도우미","title":"표준예방접종일정표(2026)","url":"https://nip.kdca.go.kr/irhp/infm/goImgPopup.do?num=1","checked":"2026-09-13"},{"org":"질병관리청 예방접종도우미","title":"국가예방접종사업","url":"https://nip.kdca.go.kr/irhp/infm/goVcntInfo.do?menuLv=1&menuCd=131","checked":"2026-09-13"}],"verified":true,"note":null},{"id":"baby0-checkup-2","stage":"baby-0","kind":"screening","who":"부부","title":"영유아 건강검진 2차","summary":"영유아 건강검진 2차의 검진 시기는 생후 4~6개월이에요. 건강보험가입자는 공단이 전액 부담해 본인부담이 없어요. 개인 일정은 의료기관과 상의해요.","steps":["국민건강보험 누리집 영유아 검진대상 조회에서 검진기관을 찾아요","검진 시기 안에 예약하고 문진표를 준비해요"],"where":"전국 영유아 검진기관(국민건강보험 누리집에서 조회)","amount":"본인부담 없음","eligibility":"생후 14일부터 71개월까지의 영유아","timing":{"anchor":"birth","from_days":120,"to_days":180,"label":"생후 4~6개월"},"region":"전국","sources":[{"org":"국민건강보험공단","title":"영유아 건강검진 안내","url":"https://www.nhis.or.kr/nhis/healthin/wbhaca04800m01.do","checked":"2026-09-13"}],"verified":true,"note":"검진 시기를 넘겼을 때의 처리는 원문에서 확인하지 못했어요."},{"id":"baby0-vaccine-6months","stage":"baby-0","kind":"vaccine","who":"부부","title":"생후 6개월 무렵 접종 묶음","summary":"표준예방접종일정표(2026)에서 6개월에 있는 국가예방접종은 B형간염 3차, 디프테리아 파상풍 백일해 3차, 폴리오 3차(6~18개월)예요. b형헤모필루스인플루엔자 3차, 폐렴구균 감염증 3차, 로타바이러스 감염증 RV5 3차, 인플루엔자(6개월부터 매년 접종)도 있어요. 위탁의료기관과 보건소에서 비용부담 없이 받을 수 있어요. 개인 일정은 의료기관과 상의해요.","loses":"위탁의료기관 밖에서 접종하면 예방접종 비용을 지원받을 수 없어요.","steps":["예방접종도우미에서 위탁의료기관을 찾아요","접종 후 예방접종도우미에서 기록을 확인해요"],"where":"위탁의료기관, 보건소(예방접종도우미 nip.kdca.go.kr에서 검색)","amount":"국가예방접종 비용부담 없음","eligibility":"12세 이하 어린이(2026년도 기준 2013.1.1. 이후 출생자)","timing":{"anchor":"birth","from_days":180,"to_days":359,"label":"6개월"},"region":"전국","sources":[{"org":"질병관리청 예방접종도우미","title":"표준예방접종일정표(2026)","url":"https://nip.kdca.go.kr/irhp/infm/goImgPopup.do?num=1","checked":"2026-09-13"},{"org":"질병관리청 예방접종도우미","title":"국가예방접종사업","url":"https://nip.kdca.go.kr/irhp/infm/goVcntInfo.do?menuLv=1&menuCd=131","checked":"2026-09-13"}],"verified":true,"note":"인플루엔자는 절기마다 접종 기간이 따로 공지돼요."},{"id":"baby0-checkup-3","stage":"baby-0","kind":"screening","who":"부부","title":"영유아 건강검진 3차","summary":"영유아 건강검진 3차의 검진 시기는 생후 9~12개월이에요. 건강보험가입자는 공단이 전액 부담해 본인부담이 없어요. 개인 일정은 의료기관과 상의해요.","steps":["국민건강보험 누리집 영유아 검진대상 조회에서 검진기관을 찾아요","검진 시기 안에 예약하고 문진표를 준비해요"],"where":"전국 영유아 검진기관(국민건강보험 누리집에서 조회)","amount":"본인부담 없음","eligibility":"생후 14일부터 71개월까지의 영유아","timing":{"anchor":"birth","from_days":270,"to_days":360,"label":"생후 9~12개월"},"region":"전국","sources":[{"org":"국민건강보험공단","title":"영유아 건강검진 안내","url":"https://www.nhis.or.kr/nhis/healthin/wbhaca04800m01.do","checked":"2026-09-13"}],"verified":true,"note":"검진 시기를 넘겼을 때의 처리는 원문에서 확인하지 못했어요."},{"id":"baby0-vaccine-12months","stage":"baby-0","kind":"vaccine","who":"부부","title":"생후 12개월 무렵 접종 묶음","summary":"표준예방접종일정표(2026)에서 12개월부터 시작하는 국가예방접종은 b형헤모필루스인플루엔자 4차(12~15개월), 폐렴구균 감염증 4차(12~15개월)예요. 홍역 유행성이하선염 풍진 1차(12~15개월), 수두 1차(12~15개월)도 있어요. A형간염 1~2차, 일본뇌염 불활성화 백신 1~2차 또는 약독화 생백신 1차도 있어요. 위탁의료기관과 보건소에서 비용부담 없이 받을 수 있어요. 개인 일정은 의료기관과 상의해요.","loses":"위탁의료기관 밖에서 접종하면 예방접종 비용을 지원받을 수 없어요.","steps":["예방접종도우미에서 위탁의료기관을 찾아요","접종 후 예방접종도우미에서 기록을 확인해요"],"where":"위탁의료기관, 보건소(예방접종도우미 nip.kdca.go.kr에서 검색)","amount":"국가예방접종 비용부담 없음","eligibility":"12세 이하 어린이(2026년도 기준 2013.1.1. 이후 출생자)","timing":{"anchor":"birth","from_days":360,"to_days":450,"label":"12~15개월"},"region":"전국","sources":[{"org":"질병관리청 예방접종도우미","title":"표준예방접종일정표(2026)","url":"https://nip.kdca.go.kr/irhp/infm/goImgPopup.do?num=1","checked":"2026-09-13"},{"org":"질병관리청 예방접종도우미","title":"국가예방접종사업","url":"https://nip.kdca.go.kr/irhp/infm/goVcntInfo.do?menuLv=1&menuCd=131","checked":"2026-09-13"}],"verified":true,"note":"A형간염과 일본뇌염은 일정표에서 12개월 열부터 시작하는 막대로 표시돼요. 끝나는 시기는 다음 구간 카드에서 다뤄요. 디프테리아 파상풍 백일해 4차는 15~18개월이라 넣지 않았어요."},{"id":"baby0-parental-leave-benefit-deadline","stage":"baby-0","kind":"work-right","who":"부부","title":"육아휴직 급여 신청 기한","summary":"고용보험에서 주는 육아휴직 급여는 휴직을 시작한 뒤 정해진 기간 안에 직접 신청해야 해요.","loses":"육아휴직이 끝난 날 이후 12개월이 지나면 급여를 신청할 수 없어요.","steps":["회사가 육아휴직 확인서를 고용센터에 내요","휴직 시작 1개월 뒤부터 고용24 또는 고용센터에 급여를 신청해요"],"where":"고용24, 관할 고용센터","amount":null,"eligibility":"육아휴직을 30일 이상 부여받고 휴직 시작 전 피보험 단위기간이 합산 180일 이상인 근로자","timing":{"anchor":"birth","from_days":null,"to_days":null,"label":"육아휴직을 시작한 날 이후 1개월부터 육아휴직이 끝난 날 이후 12개월 이내"},"region":"전국","sources":[{"org":"법제처 국가법령정보센터","title":"고용보험법 제70조(육아휴직 급여)","url":"https://www.law.go.kr/LSW//lsLawLinkInfo.do?lsJoLnkSeq=1000954287&lsId=001761&chrClsCd=010202&print=print","checked":"2026-09-13"}],"verified":true,"note":"시행일 2026-08-20 조문 기준이에요. 대통령령으로 정한 사유로 신청하지 못했으면 그 사유가 끝난 후 30일 이내에 신청해요. 기한은 휴직 시작일과 종료일을 기준으로 해요."},{"id":"baby1-vaccine-12-15m","stage":"baby-1","kind":"vaccine","who":"부부","title":"12~15개월 국가예방접종","summary":"표준예방접종일정표(2026)는 12~15개월 접종을 이렇게 정해요. 홍역·유행성이하선염·풍진(MMR) 1차, 수두 1차, b형헤모필루스인플루엔자(Hib) 4차, 폐렴구균 4차예요. 보건소와 위탁의료기관에서 접종비용을 전액 지원해요. 개인 일정은 의료기관과 상의해요.","loses":"위탁의료기관이 아닌 곳에서 접종하면 비용 지원을 받을 수 없어요. Hib·폐렴구균 지원은 생후 59개월까지예요.","steps":["예방접종도우미 누리집에서 접종 내역과 가까운 위탁의료기관을 확인해요","위탁의료기관에 접종 가능한 백신을 전화로 확인해요","보호자 신분증과 예방접종수첩을 챙겨 방문해요","예진표를 쓰고 의사 예진을 받은 뒤 접종해요"],"where":"전국 보건소 및 위탁의료기관","amount":"접종비용(백신비·예방접종 시행비) 전액 지원","eligibility":"12세 이하 어린이(2013.1.1. 이후 출생자, 2026년도 기준)예요.","timing":{"anchor":"birth","from_days":360,"to_days":450,"label":"12개월~15개월"},"region":"전국","sources":[{"org":"질병관리청 예방접종도우미","title":"표준 예방접종 일정표(표준예방접종일정표 2026)","url":"https://nip.kdca.go.kr/irhp/infm/goVcntInfo.do?menuLv=1&menuCd=115","checked":"2026-09-13"},{"org":"질병관리청 예방접종도우미","title":"국가예방접종사업","url":"https://nip.kdca.go.kr/irhp/infm/goVcntInfo.do?menuLv=1&menuCd=131","checked":"2026-09-13"}],"verified":true,"note":"DTaP·IPV·Hib·PCV·IJEV 등은 접종이 늦어지면 일정(횟수)이 달라진다고 원문에 나와 있어요. 일정표는 개정될 수 있어요."},{"id":"baby1-vaccine-hepa-je-12-35m","stage":"baby-1","kind":"vaccine","who":"부부","title":"A형간염·일본뇌염 국가예방접종(12~35개월)","summary":"표준예방접종일정표(2026)에서 A형간염 1~2차는 12~35개월이에요. 일본뇌염 불활성화 백신은 1~2차가 12~23개월, 3차가 24~35개월이에요. 약독화 생백신은 1차가 12~23개월, 2차가 24~35개월이에요. 개인 일정은 의료기관과 상의해요.","loses":"일본뇌염 약독화 생백신 중 이모젭은 국가예방접종에 들어가지 않아요. 그래서 접종비용을 전액 본인이 내요.","steps":["위탁의료기관에서 일본뇌염 백신 종류(불활성화·약독화 생백신)를 확인해요","보호자 신분증과 예방접종수첩을 챙겨 방문해요","예진 뒤 접종하고 다음 차수 날짜를 안내받아요"],"where":"전국 보건소 및 위탁의료기관","amount":"국가예방접종 백신은 접종비용 전액 지원(이모젭은 본인 부담)","eligibility":"12세 이하 어린이(2013.1.1. 이후 출생자, 2026년도 기준)예요. A형간염은 2012년 1월 1일 출생아부터 지원해요.","timing":{"anchor":"birth","from_days":360,"to_days":1050,"label":"12개월~35개월(일본뇌염 추가 차수는 24~35개월)"},"region":"전국","sources":[{"org":"질병관리청 예방접종도우미","title":"표준 예방접종 일정표(표준예방접종일정표 2026)","url":"https://nip.kdca.go.kr/irhp/infm/goVcntInfo.do?menuLv=1&menuCd=115","checked":"2026-09-13"},{"org":"질병관리청 예방접종도우미","title":"국가예방접종사업","url":"https://nip.kdca.go.kr/irhp/infm/goVcntInfo.do?menuLv=1&menuCd=131","checked":"2026-09-13"}],"verified":true,"note":"일정표 이미지의 막대 구간을 읽은 값이에요. 차수 사이 간격은 의료기관에서 안내받아요."},{"id":"baby1-vaccine-flu-yearly","stage":"baby-1","kind":"vaccine","who":"부부","title":"어린이 인플루엔자 국가예방접종(매년)","summary":"생후 6개월~14세 어린이는 주소지와 관계없이 전국 위탁의료기관과 보건소에서 무료로 인플루엔자 접종을 받을 수 있어요. 처음 접종하거나 이전 접종력을 모르는 생후 6개월~9세 미만 등은 2회 지원 대상이에요. 개인 일정은 의료기관과 상의해요.","loses":"절기 사업기간이 끝나면 그 절기 무료 접종 지원도 끝나요. 2026-2027절기는 2027년 4월 30일에 끝나요.","steps":["예방접종도우미 누리집에서 이번 절기 대상과 기간을 확인해요","방문 전에 위탁의료기관에 접종 가능 여부를 확인해요","예진 뒤 접종하고 2회 대상이면 두 번째 날짜를 안내받아요"],"where":"전국 위탁의료기관 및 보건소(보건지소, 보건진료소)","amount":"무료","eligibility":"2026-2027절기에는 생후 6개월~14세 어린이(2012.1.1.~2026.8.31. 출생아)가 대상이에요.","timing":{"anchor":"birth","from_days":360,"to_days":1080,"label":"매년 접종. 2026-2027절기 2회 접종 대상 2026년 9월 21일(월)~2027년 4월 30일, 1회 접종 대상 2026년 9월 28일(월)~2027년 4월 30일"},"region":"전국","sources":[{"org":"질병관리청 예방접종도우미","title":"인플루엔자 국가예방접종(최종검토일 2026-08-25)","url":"https://nip.kdca.go.kr/irhp/infm/goVcntInfo.do?menuLv=1&menuCd=134","checked":"2026-09-13"},{"org":"질병관리청 예방접종도우미","title":"표준 예방접종 일정표(표준예방접종일정표 2026)","url":"https://nip.kdca.go.kr/irhp/infm/goVcntInfo.do?menuLv=1&menuCd=115","checked":"2026-09-13"}],"verified":true,"note":"대상 출생일 범위와 사업기간은 절기마다 새로 공지돼요. 2회 지원 조건에는 2026년 6월 30일까지 총 1회만 접종한 경우도 들어가요."},{"id":"baby1-vaccine-15-18m","stage":"baby-1","kind":"vaccine","who":"부부","title":"15~18개월 국가예방접종","summary":"표준예방접종일정표(2026)에서 15~18개월에는 디프테리아·파상풍·백일해(DTaP) 4차가 잡혀 있어요. 폴리오 3차는 6~18개월 사이예요. 보건소와 위탁의료기관에서 접종비용을 전액 지원해요. 개인 일정은 의료기관과 상의해요.","loses":"위탁의료기관이 아닌 곳에서 접종하면 비용 지원을 받을 수 없어요.","steps":["예방접종도우미 누리집에서 남은 차수와 위탁의료기관을 확인해요","보호자 신분증과 예방접종수첩을 챙겨 방문해요","예진표를 쓰고 의사 예진을 받은 뒤 접종해요"],"where":"전국 보건소 및 위탁의료기관","amount":"접종비용(백신비·예방접종 시행비) 전액 지원","eligibility":"12세 이하 어린이(2013.1.1. 이후 출생자, 2026년도 기준)예요.","timing":{"anchor":"birth","from_days":450,"to_days":540,"label":"15개월~18개월(폴리오 3차는 6개월~18개월)"},"region":"전국","sources":[{"org":"질병관리청 예방접종도우미","title":"표준 예방접종 일정표(표준예방접종일정표 2026)","url":"https://nip.kdca.go.kr/irhp/infm/goVcntInfo.do?menuLv=1&menuCd=115","checked":"2026-09-13"},{"org":"질병관리청 예방접종도우미","title":"국가예방접종사업","url":"https://nip.kdca.go.kr/irhp/infm/goVcntInfo.do?menuLv=1&menuCd=131","checked":"2026-09-13"}],"verified":true,"note":"혼합백신(DTaP-IPV 등) 사용 여부에 따라 접종 횟수가 달라질 수 있어요. 일정표는 개정될 수 있어요."},{"id":"baby1-screening-4th","stage":"baby-1","kind":"screening","who":"부부","title":"영유아 건강검진 4차","summary":"영유아 건강검진 4차는 생후 18~24개월에 받아요. 검사는 문진과 진찰, 신체계측, 발달평가 및 상담, 건강교육으로 이뤄져요. 본인부담은 없어요. 개인 일정은 의료기관과 상의해요.","loses":"영유아 검진은 차수마다 정해진 시기에 1회씩 받도록 되어 있어요. 그래서 생후 24개월을 넘기면 4차는 건너뛰게 돼요.","steps":["공단이 보낸 영유아 건강검진표(전자문서 또는 우편)를 확인해요","영유아 검진을 하는 검진기관을 골라 예약해요","영유아건강검진 문진표를 미리 작성해요","신분증을 챙겨 기간 안에 방문해요"],"where":"국민건강보험공단 지정 영유아 건강검진기관","amount":"본인부담 없음","eligibility":"건강보험 가입자 영유아와 6세 미만 의료급여수급권자가 대상이에요.","timing":{"anchor":"birth","from_days":540,"to_days":720,"label":"생후 18~24개월"},"region":"전국","sources":[{"org":"국민건강보험공단","title":"영유아 건강검진","url":"https://www.nhis.or.kr/nhis/healthin/wbhaca04800m01.do","checked":"2026-09-13"},{"org":"보건복지부(국가법령정보센터)","title":"건강검진 실시기준(고시, 2026.1.7. 시행)","url":"https://www.law.go.kr/행정규칙/건강검진실시기준","checked":"2026-09-13"}],"verified":true,"note":"고시 제8조는 영유아건강검진을 정한 시기에 1회씩 한다고 정해요. 기간을 넘겼을 때 어떻게 되는지는 공단 누리집에서 찾지 못했어요."},{"id":"baby1-screening-oral-18-29m","stage":"baby-1","kind":"screening","who":"부부","title":"영유아 구강검진(생후 18~29개월)","summary":"영유아 구강검진 첫 차수는 생후 18~29개월에 받아요. 건강검진 4차와 기간이 따로 잡혀 있어요. 본인부담은 없어요. 개인 일정은 의료기관과 상의해요.","loses":"구강검진도 정해진 시기에 1회씩이에요. 그래서 생후 29개월을 넘기면 이 차수는 건너뛰게 돼요.","steps":["영유아 구강검진을 하는 치과 검진기관을 찾아 예약해요","영유아 구강검진 문진표를 작성해요","신분증을 챙겨 기간 안에 방문해요"],"where":"국민건강보험공단 지정 구강검진기관(치과)","amount":"본인부담 없음","eligibility":"건강보험 가입자 영유아와 6세 미만 의료급여수급권자가 대상이에요.","timing":{"anchor":"birth","from_days":540,"to_days":870,"label":"생후 18~29개월"},"region":"전국","sources":[{"org":"국민건강보험공단","title":"영유아 건강검진","url":"https://www.nhis.or.kr/nhis/healthin/wbhaca04800m01.do","checked":"2026-09-13"},{"org":"보건복지부(국가법령정보센터)","title":"건강검진 실시기준(고시, 2026.1.7. 시행)","url":"https://www.law.go.kr/행정규칙/건강검진실시기준","checked":"2026-09-13"}],"verified":true,"note":"고시 청구서식에서 구강검진은 정해진 차수에만 하는 항목이에요. 그 차수는 18개월, 30개월, 42개월, 54개월이에요."},{"id":"baby1-parental-leave-6plus6","stage":"baby-1","kind":"work-right","who":"부부","title":"출생 후 18개월 이내 자녀 육아휴직 급여 특례(6+6 부모육아휴직제)","summary":"자녀가 출생 후 18개월이 될 때까지 부모가 모두 육아휴직을 하면 각자 첫 6개월 급여를 통상임금 100%로 받아요. 상한은 달마다 올라가요. 부모 휴직 기간이 겹치지 않아도 적용돼요.","loses":"생후 18개월이 넘은 뒤 부모 중 한 명이 휴직을 하면 특례가 적용되지 않아요. 이때는 일반 상한으로 받아요. 첫 3개월은 월 250만원, 4~6개월은 월 200만원이에요.","steps":["부부가 각자 휴직 기간을 자녀 생후 18개월 안으로 잡아요","휴직 시작 예정일 30일 전까지 각자 회사에 육아휴직 신청서를 내요","휴직 시작 1개월 뒤부터 각자 고용센터에 육아휴직 급여를 신청해요"],"where":"사업주(휴직 신청), 고용노동부 고용센터(급여 신청)","amount":"부모 각각 첫 6개월 월 통상임금 100%, 6개월씩 쓰면 월 상한 1·2개월째 250만원, 3개월째 300만원, 4개월째 350만원, 5개월째 400만원, 6개월째 450만원(하한 70만원). 7개월째부터 통상임금 80%(상한 160만원, 하한 70만원)","eligibility":"같은 자녀로 출생 후 18개월이 될 때까지 부모가 모두 육아휴직을 하는 경우예요. 각자 휴직 시작 전 고용보험 피보험 단위기간이 합산 180일 이상이어야 해요.","timing":{"anchor":"birth","from_days":null,"to_days":540,"label":"자녀의 출생 후 18개월이 될 때까지 피보험자인 부모가 모두 육아휴직을 하는 경우"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"고용보험법 시행령 제95조의3(출생 후 18개월 이내의 자녀에 대한 육아휴직 급여 등의 특례)","url":"https://www.law.go.kr/법령/고용보험법시행령","checked":"2026-09-13"},{"org":"국가법령정보센터","title":"고용보험법 제70조(육아휴직 급여)","url":"https://www.law.go.kr/법령/고용보험법","checked":"2026-09-13"}],"verified":true,"note":"상한은 부모가 각각 쓴 개월 수에 따라 달라요. 각 1~2개월이면 월 250만원, 각 3개월이면 셋째 달 300만원이에요. 시행령 2024.12.24 개정 조문을 2026.7.1 시행 판본에서 확인했어요."},{"id":"baby1-seoul-childcare-cost","stage":"baby-1","kind":"benefit","who":"부부","title":"서울형 아이돌봄비","summary":"서울에 사는 24~36개월 아이를 조부모 등 4촌 이내 친인척이 돌보거나 서울시가 지정한 민간 아이돌봄서비스를 쓰면 돌봄비를 지원해요. 둘 중 하나를 골라요.","loses":"신청은 매월 1~15일에만 받고, 아이가 36개월이 되는 달까지만 지원해요. 늦게 신청할수록 받을 수 있는 달이 줄어요.","steps":["복지로에서 정부지원 아이돌봄서비스(시간제)를 신청해 자격 판정(가~다형)을 먼저 받아요","아이가 23개월이 되면 매월 1~15일에 탄생육아 몽땅정보통에서 신청해요","자치구가 매월 25일까지 자격을 확인하고 대상을 정해요","이용 전월 말까지 친인척은 조력자 회원가입과 사전교육, 민간형은 기관 선택과 가입을 마쳐요","돌봄 활동 후 다음 달 20일에 돌봄비를 받아요"],"where":"탄생육아 몽땅정보통(umppa.seoul.go.kr), 마포구청 02-3153-8925","amount":"친인척형: 월 40시간 충족 시 영아 1명 월 30만원, 2명 월 45만원, 3명 월 60만원. 민간형: 영아 1명 시간당 7,500원(월 15~30만원)","eligibility":"부모와 아동(24~36개월) 모두 서울에 주민등록이 있어야 해요. 아이와 부 또는 모의 주소가 같아야 해요. 중위소득 150% 이하여야 하고, 맞벌이는 부부 합산소득을 25% 줄여 계산해요. 맞벌이·한부모·다자녀 등 양육 공백이 있는 가정이 대상이에요.","timing":{"anchor":"birth","from_days":690,"to_days":1080,"label":"아동이 23개월부터 신청 가능, 24개월부터 36개월이 되는 달 말일까지 이용 및 지원"},"region":"서울","sources":[{"org":"서울특별시 탄생육아 몽땅정보통","title":"서울형 아이돌봄비","url":"https://umppa.seoul.go.kr/hmpg/sprt/sesu/bzin/bzmgPageDetail.do?biz_mng_no=59F45FE9BC024848AD07143C962E6869","checked":"2026-09-13"}],"verified":true,"note":"누리집 소득 기준표는 2025년 기준 중위소득(3인 이하 월 7,539천원 등)으로 적혀 있어요. 그래서 2026년 기준액은 확인하지 못했어요. 친인척 돌봄은 하루 4시간까지만 인정해요. 어린이집 다니는 아이는 기본보육시간(9~16시)을 빼고 계산해요. 해당 월에 정부지원 아이돌봄서비스를 쓰면 지원하지 않아요."},{"id":"baby1-screening-5th","stage":"baby-1","kind":"screening","who":"부부","title":"영유아 건강검진 5차","summary":"영유아 건강검진 5차는 생후 30~36개월에 받아요. 검사는 문진과 진찰, 신체계측, 발달평가 및 상담, 건강교육으로 이뤄져요. 본인부담은 없어요. 개인 일정은 의료기관과 상의해요.","loses":"생후 36개월을 넘기면 5차 검진은 건너뛰게 돼요.","steps":["공단이 보낸 영유아 건강검진표를 확인해요","검진기관을 골라 예약해요","영유아건강검진 문진표를 미리 작성해요","신분증을 챙겨 기간 안에 방문해요"],"where":"국민건강보험공단 지정 영유아 건강검진기관","amount":"본인부담 없음","eligibility":"건강보험 가입자 영유아와 6세 미만 의료급여수급권자가 대상이에요.","timing":{"anchor":"birth","from_days":900,"to_days":1080,"label":"생후 30~36개월"},"region":"전국","sources":[{"org":"국민건강보험공단","title":"영유아 건강검진","url":"https://www.nhis.or.kr/nhis/healthin/wbhaca04800m01.do","checked":"2026-09-13"},{"org":"보건복지부(국가법령정보센터)","title":"건강검진 실시기준(고시, 2026.1.7. 시행)","url":"https://www.law.go.kr/행정규칙/건강검진실시기준","checked":"2026-09-13"}],"verified":true,"note":"기간을 넘겼을 때 어떻게 되는지는 공단 누리집에서 찾지 못했어요. 고시 제8조의 차수별 1회 규정을 근거로 적었어요."},{"id":"baby1-screening-oral-30-41m","stage":"baby-1","kind":"screening","who":"부부","title":"영유아 구강검진(생후 30~41개월)","summary":"영유아 구강검진 두 번째 차수는 생후 30~41개월에 받아요. 본인부담이 없어요. 개인 일정은 의료기관과 상의해요.","loses":"생후 41개월을 넘기면 이 차수 구강검진은 건너뛰게 돼요.","steps":["영유아 구강검진을 하는 치과 검진기관을 찾아 예약해요","영유아 구강검진 문진표를 작성해요","신분증을 챙겨 기간 안에 방문해요"],"where":"국민건강보험공단 지정 구강검진기관(치과)","amount":"본인부담 없음","eligibility":"건강보험 가입자 영유아와 6세 미만 의료급여수급권자가 대상이에요.","timing":{"anchor":"birth","from_days":900,"to_days":1230,"label":"생후 30~41개월"},"region":"전국","sources":[{"org":"국민건강보험공단","title":"영유아 건강검진","url":"https://www.nhis.or.kr/nhis/healthin/wbhaca04800m01.do","checked":"2026-09-13"},{"org":"보건복지부(국가법령정보센터)","title":"건강검진 실시기준(고시, 2026.1.7. 시행)","url":"https://www.law.go.kr/행정규칙/건강검진실시기준","checked":"2026-09-13"}],"verified":true,"note":"기간 끝이 36개월을 넘어서 다음 단계 항목과 겹칠 수 있어요."},{"id":"baby1-childcare-fee-apply","stage":"baby-1","kind":"childcare","who":"부부","title":"보육료 지원 신청(어린이집 입소)","summary":"어린이집을 이용하면 정부지원 보육료를 신청해서 받아요. 부모급여(12~23개월 월 50만원)를 받는 아이가 어린이집에 다니면 부모급여가 보육료 바우처로 나와요. 2026년 기준 12~23개월 아동은 0세반·1세반 모두 현금으로 받는 차액이 없어요.","loses":"보육료는 신청일부터 지원해요. 입소한 뒤에 늦게 신청하면 입소일과 신청일 사이 보육료는 받지 못해요.","steps":["어린이집 입소가 확정되면 입소일을 확인해요","입소일 전에 복지로 누리집이나 주민센터에서 보육료 지원을 신청해요","신청 후 14일 안에 나오는 결과를 확인해요","24개월 이후에도 어린이집에 다니면 가정양육수당(월 10만원) 대신 보육료로 지원받아요"],"where":"복지로(www.bokjiro.go.kr) 또는 주민센터","amount":"2026년 정부지원보육료 단가(기본보육) 0세반 58.4만원, 1세반 51.5만원, 2세반 42.6만원","eligibility":"어린이집을 이용하는 0~5세 아동이에요(소득 무관).","timing":{"anchor":"birth","from_days":null,"to_days":null,"label":"어린이집 입소일 전(신청일을 기준으로 지원하며, 신청일보다 입소일이 늦으면 입소일부터 지원)"},"region":"전국","sources":[{"org":"서울특별시","title":"부모급여, 가정양육수당, 보육료를 지원 받고 계신가요?","url":"https://news.seoul.go.kr/welfare/archives/114481","checked":"2026-09-13"},{"org":"아이사랑(한국사회보장정보원)","title":"[필독] 2026년 보육료 인상 및 부모급여 차액 관련 공지","url":"https://www.childcare.go.kr/index.html?menuno=325&flag=Sl&bgb=1&bid=1895876&BVIEWGB=2","checked":"2026-09-13"},{"org":"보건복지부","title":"부모급여(영아수당) 지급","url":"https://www.mohw.go.kr/menu.es?mid=a10711030600","checked":"2026-09-13"}],"verified":true,"note":"서울시 안내문과 아이사랑 공지의 보육료 금액이 서로 달라요. 서울시 안내문은 0세 1,277,000원, 1세 892,000원, 2세 682,000원이에요. 아이사랑 공지의 정부지원 단가는 58.4만·51.5만·42.6만원이에요. 서울시 금액은 다른 지원분을 합친 값으로 보이지만 원문에 설명이 없어요. 단가는 해마다 바뀌어요."},{"id":"baby1-kindergarten-firstschool","stage":"baby-1","kind":"deadline","who":"부부","title":"유치원 입학 원서 접수(처음학교로)","summary":"유치원 입학은 교육부 유치원입학관리시스템(처음학교로)에서 우선모집, 일반모집, 추가모집 순서로 원서를 받아요. 입학은 추첨으로 정해요. 누리집 안내로는 2027학년도 유아모집 서비스가 2026년 10월에 열릴 예정이에요.","loses":"원서 접수 기간을 넘기면 그 학년도 추첨에 들어가지 못해요. 그때는 결원이 난 유치원을 따로 찾아야 해요.","steps":["처음학교로 회원가입 후 자녀를 등록해요","모집요강 찾기에서 지원할 유치원의 모집요강을 확인해요","우선모집 대상이면 우선모집 기간에 원서를 내요","일반모집 기간에 원서를 내요","추첨·발표를 확인하고 등록 기간 안에 등록해요"],"where":"유치원입학관리시스템 처음학교로(www.go-firstschool.go.kr)","amount":null,"eligibility":"유치원 입학을 원하는 유아예요. 연령·우선모집 기준은 학년도마다 모집요강에서 정해요.","timing":{"anchor":"birth","from_days":null,"to_days":null,"label":"만 3세 반 입학 전년도 10~11월(예: 2023학년도 우선모집 원서접수 10월 31일~11월 2일, 일반모집 원서접수 11월 16일~11월 18일). 2027학년도 서비스는 2026년 10월 예정"},"region":"전국","sources":[{"org":"교육부 유치원입학관리시스템","title":"유치원입학 처음학교로(2027학년도 유아모집 서비스 제공 예정 안내)","url":"https://www.go-firstschool.go.kr/PAMS_SS/selectHm10mGridList.do","checked":"2026-09-13"},{"org":"복지로","title":"유치원 입학관리시스템 '처음학교로' 모집 일정 안내","url":"https://m.bokjiro.go.kr/ssis-tem/cms/mob/news/promotion/1303951_1166.html","checked":"2026-09-13"}],"verified":false,"note":"2027학년도 원서 접수 날짜는 아직 공고 전이라 넣지 못했어요. 날짜 예시는 2023학년도 안내예요. 만 3세 반 대상 출생연도, 우선모집 대상, 서울시교육청 세부 일정은 2026년 10월 이후 공고에서 확인해야 해요."},{"id":"baby1-parental-leave","stage":"baby-1","kind":"work-right","who":"부부","title":"육아휴직","summary":"만 8세 이하 또는 초등학교 2학년 이하 자녀를 키우는 근로자는 1년 이내로 육아휴직을 쓸 수 있어요. 같은 자녀로 부모가 각각 3개월 이상 쓰면 6개월을 더 쓸 수 있어요. 3회까지 나눠 쓸 수 있어요.","loses":"육아휴직 급여는 휴직이 끝난 날 이후 12개월 안에 신청해야 해요. 이 기한을 넘기면 급여를 받지 못해요.","steps":["휴직 시작 예정일 30일 전까지 회사에 육아휴직 신청서를 내요","회사는 신청일부터 14일 안에 허용 사실을 알려야 하고, 알리지 않으면 신청한 대로 허용된 것으로 봐요","휴직 시작 1개월 뒤부터 고용센터에 급여를 신청해요","휴직이 끝난 날 이후 12개월 안에 급여 신청을 마쳐요"],"where":"사업주(휴직 신청), 고용노동부 고용센터(급여 신청)","amount":"1~3개월 월 통상임금 100%(상한 250만원), 4~6개월 월 통상임금 100%(상한 200만원), 7개월째부터 통상임금 80%(상한 160만원). 하한 월 70만원","eligibility":"만 8세 이하 또는 초등학교 2학년 이하 자녀를 둔 근로자예요. 계속 근로 6개월 미만이면 사업주가 거부할 수 있어요. 급여는 30일 이상 휴직하고 피보험 단위기간이 합산 180일 이상이어야 받아요.","timing":{"anchor":"birth","from_days":null,"to_days":null,"label":"자녀가 만 8세 이하 또는 초등학교 2학년 이하일 때. 급여는 육아휴직을 시작한 날 이후 1개월부터 끝난 날 이후 12개월 이내 신청"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"남녀고용평등과 일ㆍ가정 양립 지원에 관한 법률 제19조, 제19조의4","url":"https://www.law.go.kr/법령/남녀고용평등과일ㆍ가정양립지원에관한법률","checked":"2026-09-13"},{"org":"국가법령정보센터","title":"남녀고용평등과 일ㆍ가정 양립 지원에 관한 법률 시행령 제10조, 제11조","url":"https://www.law.go.kr/법령/남녀고용평등과일ㆍ가정양립지원에관한법률시행령","checked":"2026-09-13"},{"org":"국가법령정보센터","title":"고용보험법 제70조(육아휴직 급여)","url":"https://www.law.go.kr/법령/고용보험법","checked":"2026-09-13"},{"org":"국가법령정보센터","title":"고용보험법 시행령 제95조(육아휴직 급여)","url":"https://www.law.go.kr/법령/고용보험법시행령","checked":"2026-09-13"}],"verified":true,"note":"2026.8.20부터 1년에 1회, 1주 또는 2주 단위 육아휴직도 쓸 수 있어요. 휴원·휴교·방학·자녀 질병 등이 사유일 때예요. 이 기간은 육아휴직 기간에 들어가고, 분할 횟수에는 세지 않아요. 법 조문은 신청 기한만 정해요. 천재지변, 본인이나 배우자 질병 등 사유가 있으면 사유가 끝난 뒤 30일 이내에 신청할 수 있어요. 급여액은 시행령 개정으로 바뀔 수 있어요."},{"id":"baby1-reduced-hours","stage":"baby-1","kind":"work-right","who":"부부","title":"육아기 근로시간 단축","summary":"만 12세 이하 또는 초등학교 6학년 이하 자녀를 키우는 근로자는 주 15시간 이상 35시간 이하로 근로시간을 줄일 수 있어요. 기간은 1년 이내예요. 쓰지 않은 육아휴직 기간이 있으면 그 두 배를 더할 수 있어요. 1회 1개월 이상으로 나눠 쓸 수 있어요.","loses":"단축 급여는 단축이 끝난 날 이후 12개월 안에 신청해야 해요. 이 기한을 넘기면 급여를 받지 못해요.","steps":["쓰지 않은 육아휴직 기간을 계산해 단축 가능 기간을 확인해요","회사에 육아기 근로시간 단축을 신청하고 단축 후 근로조건을 서면으로 정해요","단축 시작 1개월 뒤부터 고용센터에 급여를 신청해요","단축이 끝난 날 이후 12개월 안에 급여 신청을 마쳐요"],"where":"사업주(단축 신청), 고용노동부 고용센터(급여 신청)","amount":"매주 최초 10시간 단축분은 월 통상임금 100%(상한 250만원, 하한 50만원) 기준, 나머지 단축분은 월 통상임금 80%(상한 160만원, 하한 50만원) 기준으로 단축 시간에 비례해 계산","eligibility":"만 12세 이하 또는 초등학교 6학년 이하 자녀를 둔 근로자예요. 급여는 30일 이상 단축하고 피보험 단위기간이 합산 180일 이상이어야 받아요.","timing":{"anchor":"birth","from_days":null,"to_days":null,"label":"자녀가 만 12세 이하 또는 초등학교 6학년 이하일 때. 급여는 단축을 시작한 날 이후 1개월부터 끝난 날 이후 12개월 이내 신청"},"region":"전국","sources":[{"org":"국가법령정보센터","title":"남녀고용평등과 일ㆍ가정 양립 지원에 관한 법률 제19조의2~제19조의4","url":"https://www.law.go.kr/법령/남녀고용평등과일ㆍ가정양립지원에관한법률","checked":"2026-09-13"},{"org":"국가법령정보센터","title":"고용보험법 제73조의2(육아기 근로시간 단축 급여)","url":"https://www.law.go.kr/법령/고용보험법","checked":"2026-09-13"},{"org":"국가법령정보센터","title":"고용보험법 시행령 제104조의2(육아기 근로시간 단축 급여)","url":"https://www.law.go.kr/법령/고용보험법시행령","checked":"2026-09-13"}],"verified":true,"note":"대상 연령(만 12세 이하)과 더하는 기간은 2024.10.22에 개정됐어요. 더하는 기간은 쓰지 않은 육아휴직 기간의 두 배예요. 급여 계산식은 2025.12.23 개정 시행령(2026.1.1 시행)을 반영한 판본에서 확인했어요. 사업주는 대체인력을 뽑을 수 없는 등의 사유가 있으면 거부할 수 있어요. 이때는 서면으로 알려야 해요."}];
